-- ============================================================================
-- 0027_bestiary_monster_tokens_part3of3.sql
--
-- Full SRD 5.1 bestiary (~327 monsters, CC-BY-4.0) as 'monster' tokens with
-- full statblocks + first-letter monogram placeholder art. Run all 3 parts,
-- in any order. Idempotent: skips a monster you already have by the same name.
-- Attribution: D&D 5.1 SRD, CC-BY-4.0 (see details.source).
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, creature_type, details)
  select me, v.name, v.image_url, 'monster', v.size, v.ctype,
         jsonb_build_object('kind','monster','monster', v.mb::jsonb)
  from (values
    ('Otyugh', '/icons/monsters/_mono/O.svg', 'large', 'aberration', '{"name":"Otyugh","size":"large","type":"aberration","ac":14,"hp":114,"speed":{"walk":30},"abilities":{"str":16,"dex":11,"con":19,"int":6,"wis":13,"cha":6},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"12d10 + 48","saves":{"con":7},"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Otyugh"],"traits":[{"name":"Limited Telepathy","text":"The otyugh can magically transmit simple messages and images to any creature within 120 feet of it that can understand a language. This form of telepathy doesn''t allow the receiving creature to telepathically respond."}],"actions":[{"name":"Multiattack","text":"The otyugh makes three attacks: one with its bite and two with its tentacles."},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 12 (2d8 + 3) piercing damage. If the target is a creature, it must succeed on a DC 15 Constitution saving throw against disease or become poisoned until the disease is cured. Every 24 hours that elapse, the target must repeat the saving throw, reducing its hit point maximum by 5 (1d10) on a failure. The disease is cured on a success. The target dies if the disease reduces its hit point maximum to 0. This reduction to the target''s hit point maximum lasts until the disease is cured.","attackBonus":6,"reach":"5 ft","damage":"2d8+3","damageType":"piercing","saveDc":15,"saveAbility":"con"},{"name":"Tentacle","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 7 (1d8 + 3) bludgeoning damage plus 4 (1d8) piercing damage. If the target is Medium or smaller, it is grappled (escape DC 13) and restrained until the grapple ends. The otyugh has two tentacles, each of which can grapple one target.","attackBonus":6,"reach":"10 ft","damage":"1d8+3","damageType":"bludgeoning"},{"name":"Tentacle Slam","text":"The otyugh slams creatures grappled by it into each other or a solid surface. Each creature must succeed on a DC 14 Constitution saving throw or take 10 (2d6 + 3) bludgeoning damage and be stunned until the end of the otyugh''s next turn. On a successful save, the target takes half the bludgeoning damage and isn''t stunned.","saveDc":14,"saveAbility":"con"}]}'),
    ('Owl', '/icons/monsters/_mono/O.svg', 'tiny', 'beast', '{"name":"Owl","size":"tiny","type":"beast","ac":11,"hp":1,"speed":{"walk":5,"fly":60},"abilities":{"str":3,"dex":13,"con":8,"int":2,"wis":12,"cha":7},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":3}],"senses":["Darkvision 120 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Flyby","text":"The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."},{"name":"Keen Hearing and Sight","text":"The owl has advantage on Wisdom (Perception) checks that rely on hearing or sight."}],"actions":[{"name":"Talons","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","attackBonus":3,"reach":"5 ft"}]}'),
    ('Owlbear', '/icons/monsters/_mono/O.svg', 'large', 'monstrosity', '{"name":"Owlbear","size":"large","type":"monstrosity","ac":13,"hp":59,"speed":{"walk":40},"abilities":{"str":20,"dex":12,"con":17,"int":3,"wis":12,"cha":7},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"7d10 + 21","skills":[{"name":"Perception","bonus":3}],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Sight and Smell","text":"The owlbear has advantage on Wisdom (Perception) checks that rely on sight or smell."}],"actions":[{"name":"Multiattack","text":"The owlbear makes two attacks: one with its beak and one with its claws."},{"name":"Beak","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one creature. Hit: 10 (1d10 + 5) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"1d10+5","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+5","damageType":"slashing"}]}'),
    ('Panther', '/icons/monsters/_mono/P.svg', 'medium', 'beast', '{"name":"Panther","size":"medium","type":"beast","ac":12,"hp":13,"speed":{"walk":50,"climb":40},"abilities":{"str":14,"dex":15,"con":10,"int":3,"wis":14,"cha":7},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8","skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":6}],"senses":["Passive Perception 14"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The panther has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pounce","text":"If the panther moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 12 Strength saving throw or be knocked prone. If the target is prone, the panther can make one bite attack against it as a bonus action."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"slashing"}]}'),
    ('Pegasus', '/icons/monsters/_mono/P.svg', 'large', 'celestial', '{"name":"Pegasus","size":"large","type":"celestial","ac":12,"hp":59,"speed":{"walk":60,"fly":90},"abilities":{"str":18,"dex":15,"con":16,"int":10,"wis":15,"cha":13},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","hitDice":"7d10 + 21","saves":{"dex":4,"wis":4,"cha":3},"skills":[{"name":"Perception","bonus":6}],"senses":["Passive Perception 16"],"languages":["Celestial","Common","Elvish  and Sylvan but can''t speak"],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"}]}'),
    ('Phase Spider', '/icons/monsters/_mono/P.svg', 'large', 'monstrosity', '{"name":"Phase Spider","size":"large","type":"monstrosity","ac":13,"hp":32,"speed":{"walk":30,"climb":30},"abilities":{"str":15,"dex":15,"con":12,"int":6,"wis":10,"cha":6},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d10 + 5","skills":[{"name":"Stealth","bonus":6}],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Ethereal Jaunt","text":"As a bonus action, the spider can magically shift from the Material Plane to the Ethereal Plane, or vice versa."},{"name":"Spider Climb","text":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Walker","text":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 18 (4d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Pit Fiend', '/icons/monsters/_mono/P.svg', 'large', 'fiend', '{"name":"Pit Fiend","size":"large","type":"fiend","ac":19,"hp":300,"speed":{"walk":30,"fly":60},"abilities":{"str":26,"dex":14,"con":24,"int":22,"wis":18,"cha":24},"cr":"20","proficiencyBonus":6,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"24d10 + 168","saves":{"dex":8,"con":13,"wis":10},"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 14"],"languages":["Infernal","Telepathy 120 ft."],"actions":[{"name":"Multiattack","text":"The pit fiend makes four attacks: one with its bite, one with its claw, one with its mace, and one with its tail."},{"name":"Bite","text":"Melee Weapon Attack: +14 to hit, reach 5 ft., one target. Hit: 22 (4d6 + 8) piercing damage. The target must succeed on a DC 21 Constitution saving throw or become poisoned. While poisoned in this way, the target can''t regain hit points, and it takes 21 (6d6) poison damage at the start of each of its turns. The poisoned target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":14,"reach":"5 ft","damage":"4d6+8","damageType":"piercing","saveDc":21,"saveAbility":"con"},{"name":"Claw","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 17 (2d8 + 8) slashing damage.","attackBonus":14,"reach":"10 ft","damage":"2d8+8","damageType":"slashing"},{"name":"Mace","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 15 (2d6 + 8) bludgeoning damage plus 21 (6d6) fire damage.","attackBonus":14,"reach":"10 ft","damage":"2d6+8","damageType":"bludgeoning"},{"name":"Tail","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 24 (3d10 + 8) bludgeoning damage.","attackBonus":14,"reach":"10 ft","damage":"3d10+8","damageType":"bludgeoning"}]}'),
    ('Planetar', '/icons/monsters/_mono/P.svg', 'large', 'celestial', '{"name":"Planetar","size":"large","type":"celestial","ac":19,"hp":200,"speed":{"walk":40,"fly":120},"abilities":{"str":24,"dex":20,"con":24,"int":19,"wis":22,"cha":25},"cr":"16","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"16d10 + 112","saves":{"con":12,"wis":11,"cha":12},"skills":[{"name":"Perception","bonus":11}],"damageResistances":["Radiant","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Charmed","Exhaustion","Frightened"],"senses":["Truesight 120 ft.","Passive Perception 21"],"languages":["All","Telepathy 120 ft."],"traits":[{"name":"Angelic Weapons","text":"The planetar''s weapon attacks are magical. When the planetar hits with any weapon, the weapon deals an extra 5d8 radiant damage (included in the attack)."},{"name":"Divine Awareness","text":"The planetar knows if it hears a lie."},{"name":"Innate Spellcasting","text":"The planetar''s spellcasting ability is Charisma (spell save DC 20). The planetar can innately cast the following spells, requiring no material components:"},{"name":"Magic Resistance","text":"The planetar has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The planetar makes two melee attacks."},{"name":"Greatsword","text":"Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 21 (4d6 + 7) slashing damage plus 22 (5d8) radiant damage.","attackBonus":12,"reach":"5 ft","damage":"4d6+7","damageType":"slashing"},{"name":"Healing Touch","text":"(4/Day). The planetar touches another creature. The target magically regains 30 (6d8 + 3) hit points and is freed from any curse, disease, poison, blindness, or deafness."}]}'),
    ('Plesiosaurus', '/icons/monsters/_mono/P.svg', 'large', 'beast', '{"name":"Plesiosaurus","size":"large","type":"beast","ac":13,"hp":68,"speed":{"walk":20,"swim":40},"abilities":{"str":18,"dex":15,"con":16,"int":2,"wis":12,"cha":5},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"8d10 + 24","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"The plesiosaurus can hold its breath for 1 hour."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 14 (3d6 + 4) piercing damage.","attackBonus":6,"reach":"10 ft","damage":"3d6+4","damageType":"piercing"}]}'),
    ('Poisonous Snake', '/icons/monsters/_mono/P.svg', 'tiny', 'beast', '{"name":"Poisonous Snake","size":"tiny","type":"beast","ac":13,"hp":2,"speed":{"walk":30,"swim":30},"abilities":{"str":2,"dex":16,"con":11,"int":1,"wis":10,"cha":3},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4","senses":["Blindsight 10 ft.","Passive Perception 10"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 1 piercing damage, and the target must make a DC 10 Constitution saving throw, taking 5 (2d4) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":5,"reach":"5 ft","damage":"2d4","damageType":"poison","saveDc":10,"saveAbility":"con"}]}'),
    ('Polar Bear', '/icons/monsters/_mono/P.svg', 'large', 'beast', '{"name":"Polar Bear","size":"large","type":"beast","ac":12,"hp":42,"speed":{"walk":40,"swim":30},"abilities":{"str":20,"dex":10,"con":16,"int":2,"wis":13,"cha":7},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d10 + 15","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The bear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","text":"The bear makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 9 (1d8 + 5) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"1d8+5","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+5","damageType":"slashing"}]}'),
    ('Pony', '/icons/monsters/_mono/P.svg', 'medium', 'beast', '{"name":"Pony","size":"medium","type":"beast","ac":10,"hp":11,"speed":{"walk":40},"abilities":{"str":15,"dex":10,"con":13,"int":2,"wis":11,"cha":7},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8 + 2","senses":["Passive Perception 10"],"languages":["--"],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) bludgeoning damage.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"bludgeoning"}]}'),
    ('Priest', '/icons/monsters/_mono/P.svg', 'medium', 'humanoid', '{"name":"Priest","size":"medium","type":"humanoid","ac":13,"hp":27,"speed":{"walk":25},"abilities":{"str":10,"dex":10,"con":12,"int":13,"wis":16,"cha":13},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Chain Shirt","hitDice":"5d8 + 5","skills":[{"name":"Medicine","bonus":7},{"name":"Persuasion","bonus":3},{"name":"Religion","bonus":4}],"senses":["Passive Perception 13"],"languages":["Any two languages"],"traits":[{"name":"Divine Eminence","text":"As a bonus action, the priest can expend a spell slot to cause its melee weapon attacks to magically deal an extra 10 (3d6) radiant damage to a target on a hit. This benefit lasts until the end of the turn. If the priest expends a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each level above 1st."},{"name":"Spellcasting","text":"The priest is a 5th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 13, +5 to hit with spell attacks). The priest has the following cleric spells prepared:"}],"actions":[{"name":"Mace","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 3 (1d6) bludgeoning damage.","attackBonus":2,"reach":"5 ft","damage":"1d6","damageType":"bludgeoning"}]}'),
    ('Pseudodragon', '/icons/monsters/_mono/P.svg', 'tiny', 'dragon', '{"name":"Pseudodragon","size":"tiny","type":"dragon","ac":13,"hp":7,"speed":{"walk":15,"fly":60},"abilities":{"str":6,"dex":15,"con":13,"int":10,"wis":12,"cha":10},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","acNote":"Natural Armor","hitDice":"2d4 + 2","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 13"],"languages":["Understands Common and Draconic but can''t speak them"],"traits":[{"name":"Magic Resistance","text":"The pseudodragon has advantage on saving throws against spells and other magical effects."},{"name":"Limited Telepathy","text":"The pseudodragon can magically communicate simple ideas, emotions, and images telepathically with any creature within 100 feet of it that can understand a language."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"},{"name":"Sting","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 11 Constitution saving throw or become poisoned for 1 hour. If the saving throw fails by 5 or more, the target falls unconscious for the same duration, or until it takes damage or another creature uses an action to shake it awake.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Pteranodon', '/icons/monsters/_mono/P.svg', 'medium', 'beast', '{"name":"Pteranodon","size":"medium","type":"beast","ac":13,"hp":13,"speed":{"walk":10,"fly":60},"abilities":{"str":12,"dex":15,"con":10,"int":2,"wis":9,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Flyby","text":"The pteranodon doesn''t provoke an opportunity attack when it flies out of an enemy''s reach."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"2d4+1","damageType":"piercing"}]}'),
    ('Purple Worm', '/icons/monsters/_mono/P.svg', 'gargantuan', 'monstrosity', '{"name":"Purple Worm","size":"gargantuan","type":"monstrosity","ac":18,"hp":247,"speed":{"walk":50,"burrow":30},"abilities":{"str":28,"dex":7,"con":22,"int":1,"wis":8,"cha":4},"cr":"15","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"15d20 + 90","saves":{"con":11,"wis":4},"senses":["Blindsight 30 ft.","Tremorsense 60 ft.","Passive Perception 9"],"languages":["--"],"traits":[{"name":"Tunneler","text":"The worm can burrow through solid rock at half its burrow speed and leaves a 10-foot-diameter tunnel in its wake."}],"actions":[{"name":"Multiattack","text":"The worm makes two attacks: one with its bite and one with its stinger."},{"name":"Bite","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 22 (3d8 + 9) piercing damage. If the target is a Large or smaller creature, it must succeed on a DC 19 Dexterity saving throw or be swallowed by the worm. A swallowed creature is blinded and restrained, it has total cover against attacks and other effects outside the worm, and it takes 21 (6d6) acid damage at the start of each of the worm''s turns.","attackBonus":9,"reach":"10 ft","damage":"3d8+9","damageType":"piercing","saveDc":19,"saveAbility":"dex"},{"name":"Tail Stinger","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one creature. Hit: 19 (3d6 + 9) piercing damage, and the target must make a DC 19 Constitution saving throw, taking 42 (12d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":9,"reach":"10 ft","damage":"3d6+9","damageType":"piercing","saveDc":19,"saveAbility":"con"}]}'),
    ('Quasit', '/icons/monsters/_mono/Q.svg', 'tiny', 'fiend', '{"name":"Quasit","size":"tiny","type":"fiend","ac":13,"hp":7,"speed":{"walk":40},"abilities":{"str":5,"dex":17,"con":10,"int":7,"wis":10,"cha":10},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"3d4","skills":[{"name":"Stealth","bonus":5}],"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Abyssal","Common"],"traits":[{"name":"Shapechanger","text":"The quasit can use its action to polymorph into a beast form that resembles a bat (speed 10 ft. fly 40 ft.), a centipede (40 ft., climb 40 ft.), or a toad (40 ft., swim 40 ft.), or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Magic Resistance","text":"The quasit has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Claws (Bite in Beast Form)","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage, and the target must succeed on a DC 10 Constitution saving throw or take 5 (2d4) poison damage and become poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":4,"reach":"5 ft","damage":"1d4+3","damageType":"piercing","saveDc":10,"saveAbility":"con"},{"name":"Scare (1/Day)","text":"One creature of the quasit''s choice within 20 feet of it must succeed on a DC 10 Wisdom saving throw or be frightened for 1 minute. The target can repeat the saving throw at the end of each of its turns, with disadvantage if the quasit is within line of sight, ending the effect on itself on a success.","saveDc":10,"saveAbility":"wis"},{"name":"Invisibility","text":"The quasit magically turns invisible until it attacks or uses Scare, or until its concentration ends (as if concentrating on a spell). Any equipment the quasit wears or carries is invisible with it."}]}'),
    ('Quipper', '/icons/monsters/_mono/Q.svg', 'tiny', 'beast', '{"name":"Quipper","size":"tiny","type":"beast","ac":13,"hp":1,"speed":{"walk":0,"swim":40},"abilities":{"str":2,"dex":16,"con":9,"int":1,"wis":7,"cha":2},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Blood Frenzy","text":"The quipper has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Water Breathing","text":"The quipper can breathe only underwater."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":5,"reach":"5 ft"}]}'),
    ('Rakshasa', '/icons/monsters/_mono/R.svg', 'medium', 'fiend', '{"name":"Rakshasa","size":"medium","type":"fiend","ac":16,"hp":110,"speed":{"walk":40},"abilities":{"str":14,"dex":17,"con":18,"int":13,"wis":16,"cha":20},"cr":"13","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"13d8 + 52","skills":[{"name":"Deception","bonus":10},{"name":"Insight","bonus":8}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageVulnerabilities":["Piercing from Magic Weapons Wielded by Good Creatures"],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["Common","Infernal"],"traits":[{"name":"Limited Magic Immunity","text":"The rakshasa can''t be affected or detected by spells of 6th level or lower unless it wishes to be. It has advantage on saving throws against all other spells and magical effects."},{"name":"Innate Spellcasting","text":"The rakshasa''s innate spellcasting ability is Charisma (spell save DC 18, +10 to hit with spell attacks). The rakshasa can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"Multiattack","text":"The rakshasa makes two claw attacks."},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) slashing damage, and the target is cursed if it is a creature. The magical curse takes effect whenever the target takes a short or long rest, filling the target''s thoughts with horrible images and dreams. The cursed target gains no benefit from finishing a short or long rest. The curse lasts until it is lifted by a remove curse spell or similar magic.","attackBonus":7,"reach":"5 ft","damage":"2d6+2","damageType":"slashing"}]}'),
    ('Rat', '/icons/monsters/_mono/R.svg', 'tiny', 'beast', '{"name":"Rat","size":"tiny","type":"beast","ac":10,"hp":1,"speed":{"walk":20},"abilities":{"str":2,"dex":11,"con":9,"int":2,"wis":10,"cha":4},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","senses":["Darkvision 30 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The rat has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +0 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":0,"reach":"5 ft"}]}'),
    ('Raven', '/icons/monsters/_mono/R.svg', 'tiny', 'beast', '{"name":"Raven","size":"tiny","type":"beast","ac":12,"hp":1,"speed":{"walk":10,"fly":50},"abilities":{"str":2,"dex":14,"con":8,"int":2,"wis":12,"cha":6},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Mimicry","text":"The raven can mimic simple sounds it has heard, such as a person whispering, a baby crying, or an animal chittering. A creature that hears the sounds can tell they are imitations with a successful DC 10 Wisdom (Insight) check."}],"actions":[{"name":"Beak","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":4,"reach":"5 ft"}]}'),
    ('Red Dragon Wyrmling', '/icons/monsters/_mono/R.svg', 'medium', 'dragon', '{"name":"Red Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":75,"speed":{"walk":30,"climb":30,"fly":60},"abilities":{"str":19,"dex":10,"con":17,"int":12,"wis":11,"cha":15},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"10d8 + 30","saves":{"dex":2,"con":5,"wis":2,"cha":4},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Fire"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage plus 3 (1d6) fire damage.","attackBonus":6,"reach":"5 ft","damage":"1d10+4","damageType":"piercing"},{"name":"Fire Breath (Recharge 5–6)","text":"The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 24 (7d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":13,"saveAbility":"dex"}]}'),
    ('Reef Shark', '/icons/monsters/_mono/R.svg', 'medium', 'beast', '{"name":"Reef Shark","size":"medium","type":"beast","ac":12,"hp":22,"speed":{"walk":0,"swim":40},"abilities":{"str":14,"dex":13,"con":13,"int":1,"wis":10,"cha":4},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"4d8 + 4","skills":[{"name":"Perception","bonus":2}],"senses":["Blindsight 30 ft.","Passive Perception 12"],"languages":["--"],"traits":[{"name":"Pack Tactics","text":"The shark has advantage on an attack roll against a creature if at least one of the shark''s allies is within 5 feet of the creature and the ally isn''t incapacitated."},{"name":"Water Breathing","text":"The shark can breathe only underwater."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Remorhaz', '/icons/monsters/_mono/R.svg', 'huge', 'monstrosity', '{"name":"Remorhaz","size":"huge","type":"monstrosity","ac":17,"hp":195,"speed":{"walk":30,"burrow":20},"abilities":{"str":24,"dex":13,"con":21,"int":4,"wis":10,"cha":5},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"17d12 + 85","damageImmunities":["Cold","Fire"],"senses":["Darkvision 60 ft.","Tremorsense 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Heated Body","text":"A creature that touches the remorhaz or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 40 (6d10 + 7) piercing damage plus 10 (3d6) fire damage. If the target is a creature, it is grappled (escape DC 17). Until this grapple ends, the target is restrained, and the remorhaz can''t bite another target.","attackBonus":11,"reach":"10 ft","damage":"6d10+7","damageType":"piercing"},{"name":"Swallow","text":"The remorhaz makes one bite attack against a Medium or smaller creature it is grappling. If the attack hits, that creature takes the bite''s damage and is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the remorhaz, and it takes 21 (6d6) acid damage at the start of each of the remorhaz''s turns."}]}'),
    ('Rhinoceros', '/icons/monsters/_mono/R.svg', 'large', 'beast', '{"name":"Rhinoceros","size":"large","type":"beast","ac":11,"hp":45,"speed":{"walk":40},"abilities":{"str":21,"dex":8,"con":15,"int":2,"wis":12,"cha":6},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"6d10 + 12","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Charge","text":"If the rhinoceros moves at least 20 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 (2d8) bludgeoning damage. If the target is a creature, it must succeed on a DC 15 Strength saving throw or be knocked prone."}],"actions":[{"name":"Gore","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+5","damageType":"bludgeoning"}]}'),
    ('Riding Horse', '/icons/monsters/_mono/R.svg', 'large', 'beast', '{"name":"Riding Horse","size":"large","type":"beast","ac":10,"hp":13,"speed":{"walk":60},"abilities":{"str":16,"dex":10,"con":12,"int":2,"wis":11,"cha":7},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d10 + 2","senses":["Passive Perception 10"],"languages":["--"],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (2d4 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"2d4+3","damageType":"bludgeoning"}]}'),
    ('Roc', '/icons/monsters/_mono/R.svg', 'gargantuan', 'monstrosity', '{"name":"Roc","size":"gargantuan","type":"monstrosity","ac":15,"hp":248,"speed":{"walk":20,"fly":120},"abilities":{"str":28,"dex":10,"con":20,"int":3,"wis":10,"cha":9},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"16d20 + 80","saves":{"dex":4,"con":9,"wis":4,"cha":3},"skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The roc has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The roc makes two attacks: one with its beak and one with its talons."},{"name":"Beak","text":"Melee Weapon Attack: +13 to hit, reach 10 ft., one target. Hit: 27 (4d8 + 9) piercing damage.","attackBonus":13,"reach":"10 ft","damage":"4d8+9","damageType":"piercing"},{"name":"Talons","text":"Melee Weapon Attack: +13 to hit, reach 5 ft., one target. Hit: 23 (4d6 + 9) slashing damage, and the target is grappled (escape DC 19). Until this grapple ends, the target is restrained, and the roc can''t use its talons on another target.","attackBonus":13,"reach":"5 ft","damage":"4d6+9","damageType":"slashing"}]}'),
    ('Roper', '/icons/monsters/_mono/R.svg', 'large', 'monstrosity', '{"name":"Roper","size":"large","type":"monstrosity","ac":20,"hp":93,"speed":{"walk":10,"climb":10},"abilities":{"str":18,"dex":8,"con":17,"int":7,"wis":16,"cha":6},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"11d10 + 33","skills":[{"name":"Perception","bonus":6},{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 16"],"languages":["--"],"traits":[{"name":"False Appearance","text":"While the roper remains motionless, it is indistinguishable from a normal cave formation, such as a stalagmite."},{"name":"Grasping Tendrils","text":"The roper can have up to six tendrils at a time. Each tendril can be attacked (AC 20; 10 hit points; immunity to poison and psychic damage). Destroying a tendril deals no damage to the roper, which can extrude a replacement tendril on its next turn. A tendril can also be broken if a creature takes an action and succeeds on a DC 15 Strength check against it."},{"name":"Spider Climb","text":"The roper can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."}],"actions":[{"name":"Multiattack","text":"The roper makes four attacks with its tendrils, uses Reel, and makes one attack with its bite."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 22 (4d8 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"4d8+4","damageType":"piercing"},{"name":"Tendril","text":"Melee Weapon Attack: +7 to hit, reach 50 ft., one creature. Hit: The target is grappled (escape DC 15). Until the grapple ends, the target is restrained and has disadvantage on Strength checks and Strength saving throws, and the roper can''t use the same tendril on another target.","attackBonus":7,"reach":"50 ft"},{"name":"Reel","text":"The roper pulls each creature grappled by it up to 25 feet straight toward it."}]}'),
    ('Rug of Smothering', '/icons/monsters/_mono/R.svg', 'large', 'construct', '{"name":"Rug of Smothering","size":"large","type":"construct","ac":12,"hp":33,"speed":{"walk":10},"abilities":{"str":17,"dex":14,"con":10,"int":1,"wis":3,"cha":1},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"6d10","damageImmunities":["Poison","Psychic"],"conditionImmunities":["Blinded","Charmed","Deafened","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Blindsight 60 ft.","Passive Perception 6"],"languages":["--"],"traits":[{"name":"Antimagic Susceptibility","text":"The rug is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the rug must succeed on a Constitution saving throw against the caster''s spell save DC or fall unconscious for 1 minute."},{"name":"Damage Transfer","text":"While it is grappling a creature, the rug takes only half the damage dealt to it, and the creature grappled by the rug takes the other half."},{"name":"False Appearance","text":"While the rug remains motionless, it is indistinguishable from a normal rug."}],"actions":[{"name":"Smother","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one Medium or smaller creature. Hit: The creature is grappled (escape DC 13). Until this grapple ends, the target is restrained, blinded, and at risk of suffocating, and the rug can''t smother another target. In addition, at the start of each of the target''s turns, the target takes 10 (2d6 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"bludgeoning"}]}'),
    ('Rust Monster', '/icons/monsters/_mono/R.svg', 'medium', 'monstrosity', '{"name":"Rust Monster","size":"medium","type":"monstrosity","ac":14,"hp":27,"speed":{"walk":40},"abilities":{"str":13,"dex":12,"con":13,"int":2,"wis":13,"cha":6},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d8 + 5","senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Iron Scent","text":"The rust monster can pinpoint, by scent, the location of ferrous metal within 30 feet of it."},{"name":"Rust Metal","text":"Any nonmagical weapon made of metal that hits the rust monster corrodes. After dealing damage, the weapon takes a permanent and cumulative −1 penalty to damage rolls. If its penalty drops to −5, the weapon is destroyed. Nonmagical ammunition made of metal that hits the rust monster is destroyed after dealing damage."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d8+1","damageType":"piercing"},{"name":"Antennae","text":"The rust monster corrodes a nonmagical ferrous metal object it can see within 5 feet of it. If the object isn''t being worn or carried, the touch destroys a 1-foot cube of it. If the object is being worn or carried by a creature, the creature can make a DC 11 Dexterity saving throw to avoid the rust monster''s touch.","saveDc":11,"saveAbility":"dex"}]}'),
    ('Saber-Toothed Tiger', '/icons/monsters/_mono/S.svg', 'large', 'beast', '{"name":"Saber-Toothed Tiger","size":"large","type":"beast","ac":12,"hp":52,"speed":{"walk":40},"abilities":{"str":18,"dex":14,"con":15,"int":3,"wis":12,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"7d10 + 14","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":6}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The tiger has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pounce","text":"If the tiger moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 14 Strength saving throw or be knocked prone. If the target is prone, the tiger can make one bite attack against it as a bonus action."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (1d10 + 5) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d10+5","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+5","damageType":"slashing"}]}'),
    ('Sahuagin', '/icons/monsters/_mono/S.svg', 'medium', 'humanoid', '{"name":"Sahuagin","size":"medium","type":"humanoid","ac":12,"hp":22,"speed":{"walk":30,"swim":40},"abilities":{"str":13,"dex":11,"con":12,"int":12,"wis":13,"cha":9},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"4d8 + 4","skills":[{"name":"Perception","bonus":5}],"senses":["Darkvision 120 ft.","Passive Perception 15"],"languages":["Sahuagin"],"traits":[{"name":"Blood Frenzy","text":"The sahuagin has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Limited Amphibiousness","text":"The sahuagin can breathe air and water, but it needs to be submerged at least once every 4 hours to avoid suffocating."},{"name":"Shark Telepathy","text":"The sahuagin can magically command any shark within 120 feet of it, using a limited telepathy."}],"actions":[{"name":"Multiattack","text":"The sahuagin makes two melee attacks: one with its bite and one with its claws or spear."},{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"slashing"},{"name":"Spear","text":"Melee or Ranged Weapon Attack: +3 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d6 + 1) piercing damage, or 5 (1d8 + 1) piercing damage if used with two hands to make a melee attack.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"}]}'),
    ('Salamander', '/icons/monsters/_mono/S.svg', 'large', 'elemental', '{"name":"Salamander","size":"large","type":"elemental","ac":15,"hp":90,"speed":{"walk":30},"abilities":{"str":18,"dex":14,"con":15,"int":11,"wis":10,"cha":12},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"12d10 + 24","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Fire"],"damageVulnerabilities":["Cold"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Ignan"],"traits":[{"name":"Heated Body","text":"A creature that touches the salamander or hits it with a melee attack while within 5 feet of it takes 7 (2d6) fire damage."},{"name":"Heated Weapons","text":"Any metal melee weapon the salamander wields deals an extra 3 (1d6) fire damage on a hit (included in the attack)."}],"actions":[{"name":"Multiattack","text":"The salamander makes two attacks: one with its spear and one with its tail."},{"name":"Spear","text":"Melee or Ranged Weapon Attack: +7 to hit, reach 5 ft. or range 20 ft./60 ft., one target. Hit: 11 (2d6 + 4) piercing damage, or 13 (2d8 + 4) piercing damage if used with two hands to make a melee attack, plus 3 (1d6) fire damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage plus 7 (2d6) fire damage, and the target is grappled (escape DC 14). Until this grapple ends, the target is restrained, the salamander can automatically hit the target with its tail, and the salamander can''t make tail attacks against other targets.","attackBonus":7,"reach":"10 ft","damage":"2d6+4","damageType":"bludgeoning"}]}'),
    ('Satyr', '/icons/monsters/_mono/S.svg', 'medium', 'fey', '{"name":"Satyr","size":"medium","type":"fey","ac":14,"hp":31,"speed":{"walk":40},"abilities":{"str":12,"dex":16,"con":11,"int":12,"wis":10,"cha":14},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic neutral","acNote":"Leather Armor","hitDice":"7d8","skills":[{"name":"Perception","bonus":2},{"name":"Performance","bonus":6},{"name":"Stealth","bonus":5}],"senses":["Passive Perception 12"],"languages":["Common","Elvish","Sylvan"],"traits":[{"name":"Magic Resistance","text":"The satyr has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"2d4+1","damageType":"bludgeoning"},{"name":"Shortsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"},{"name":"Shortbow","text":"Ranged Weapon Attack: +5 to hit, range 80/320 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"range 80/320 ft","damage":"1d6+3","damageType":"piercing"}]}'),
    ('Scorpion', '/icons/monsters/_mono/S.svg', 'tiny', 'beast', '{"name":"Scorpion","size":"tiny","type":"beast","ac":11,"hp":1,"speed":{"walk":10},"abilities":{"str":2,"dex":11,"con":8,"int":1,"wis":8,"cha":2},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"1d4 - 1","senses":["Blindsight 10 ft.","Passive Perception 9"],"languages":["--"],"actions":[{"name":"Sting","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 1 piercing damage, and the target must make a DC 9 Constitution saving throw, taking 4 (1d8) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":2,"reach":"5 ft","damage":"1d8","damageType":"poison","saveDc":9,"saveAbility":"con"}]}'),
    ('Scout', '/icons/monsters/_mono/S.svg', 'medium', 'humanoid', '{"name":"Scout","size":"medium","type":"humanoid","ac":13,"hp":16,"speed":{"walk":30},"abilities":{"str":11,"dex":14,"con":12,"int":11,"wis":13,"cha":11},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Leather Armor","hitDice":"3d8 + 3","skills":[{"name":"Nature","bonus":4},{"name":"Perception","bonus":5},{"name":"Stealth","bonus":6},{"name":"Survival","bonus":5}],"senses":["Passive Perception 15"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Keen Hearing and Sight","text":"The scout has advantage on Wisdom (Perception) checks that rely on hearing or sight."}],"actions":[{"name":"Multiattack","text":"The scout makes two melee attacks or two ranged attacks."},{"name":"Shortsword","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Longbow","text":"Ranged Weapon Attack: +4 to hit, ranged 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"damage":"1d8+2","damageType":"piercing"}]}'),
    ('Sea Hag', '/icons/monsters/_mono/S.svg', 'medium', 'fey', '{"name":"Sea Hag","size":"medium","type":"fey","ac":14,"hp":52,"speed":{"walk":30,"swim":40},"abilities":{"str":16,"dex":13,"con":16,"int":12,"wis":12,"cha":13},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"7d8 + 21","senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["Aquan","Common","Giant"],"traits":[{"name":"Amphibious","text":"The hag can breathe air and water."},{"name":"Horrific Appearance","text":"Any humanoid that starts its turn within 30 feet of the hag and can see the hag''s true form must make a DC 11 Wisdom saving throw. On a failed save, the creature is frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the hag is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the hag''s Horrific Appearance for the next 24 hours."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"},{"name":"Death Glare","text":"The hag targets one frightened creature she can see within 30 feet of her. If the target can see the hag, it must succeed on a DC 11 Wisdom saving throw against this magic or drop to 0 hit points.","saveDc":11,"saveAbility":"wis"},{"name":"Illusory Appearance","text":"The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like an ugly creature of her general size and humanoid shape. The effect ends if the hag takes a bonus action to end it or if she dies."}]}'),
    ('Sea Horse', '/icons/monsters/_mono/S.svg', 'tiny', 'beast', '{"name":"Sea Horse","size":"tiny","type":"beast","ac":11,"hp":1,"speed":{"walk":0,"swim":20},"abilities":{"str":1,"dex":12,"con":8,"int":1,"wis":10,"cha":2},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Water Breathing","text":"The sea horse can breathe only underwater."}]}'),
    ('Shadow', '/icons/monsters/_mono/S.svg', 'medium', 'undead', '{"name":"Shadow","size":"medium","type":"undead","ac":12,"hp":16,"speed":{"walk":40},"abilities":{"str":6,"dex":14,"con":13,"int":6,"wis":10,"cha":8},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"3d8 + 3","skills":[{"name":"Stealth","bonus":4}],"damageResistances":["Acid","Cold","Fire","Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Necrotic","Poison"],"damageVulnerabilities":["Radiant"],"conditionImmunities":["Exhaustion","Frightened","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Amorphous","text":"The shadow can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Shadow Stealth","text":"While in dim light or darkness, the shadow can take the Hide action as a bonus action."},{"name":"Sunlight Weakness","text":"While in sunlight, the shadow has disadvantage on attack rolls, ability checks, and saving throws."}],"actions":[{"name":"Strength Drain","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 9 (2d6 + 2) necrotic damage, and the target''s Strength score is reduced by 1d4. The target dies if this reduces its Strength to 0. Otherwise, the reduction lasts until the target finishes a short or long rest.","attackBonus":4,"reach":"5 ft","damage":"2d6+2","damageType":"necrotic"}]}'),
    ('Shambling Mound', '/icons/monsters/_mono/S.svg', 'large', 'plant', '{"name":"Shambling Mound","size":"large","type":"plant","ac":15,"hp":136,"speed":{"walk":20,"swim":20},"abilities":{"str":18,"dex":8,"con":16,"int":5,"wis":10,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"16d10 + 48","skills":[{"name":"Stealth","bonus":2}],"damageResistances":["Cold","Fire"],"damageImmunities":["Lightning"],"conditionImmunities":["Blinded","Deafened","Exhaustion"],"senses":["Blindsight 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Lightning Absorption","text":"Whenever the shambling mound is subjected to lightning damage, it takes no damage and regains a number of hit points equal to the lightning damage dealt."}],"actions":[{"name":"Multiattack","text":"The shambling mound makes two slam attacks. If both attacks hit a Medium or smaller target, the target is grappled (escape DC 14), and the shambling mound uses its Engulf on it."},{"name":"Slam","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"},{"name":"Engulf","text":"The shambling mound engulfs a Medium or smaller creature grappled by it. The engulfed target is blinded, restrained, and unable to breathe, and it must succeed on a DC 14 Constitution saving throw at the start of each of the mound''s turns or take 13 (2d8 + 4) bludgeoning damage. If the mound moves, the engulfed target moves with it. The mound can have only one creature engulfed at a time.","saveDc":14,"saveAbility":"con"}]}'),
    ('Shield Guardian', '/icons/monsters/_mono/S.svg', 'large', 'construct', '{"name":"Shield Guardian","size":"large","type":"construct","ac":17,"hp":142,"speed":{"walk":30},"abilities":{"str":18,"dex":8,"con":18,"int":7,"wis":10,"cha":3},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"15d10 + 60","damageImmunities":["Poison"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Poisoned"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 10"],"languages":["Understands commands given in any language but can''t speak"],"traits":[{"name":"Bound","text":"The shield guardian is magically bound to an amulet. As long as the guardian and its amulet are on the same plane of existence, the amulet''s wearer can telepathically call the guardian to travel to it, and the guardian knows the distance and direction to the amulet. If the guardian is within 60 feet of the amulet''s wearer, half of any damage the wearer takes (rounded up) is transferred to the guardian."},{"name":"Regeneration","text":"The shield guardian regains 10 hit points at the start of its turn if it has at least 1 hit point."},{"name":"Spell Storing","text":"A spellcaster who wears the shield guardian''s amulet can cause the guardian to store one spell of 4th level or lower. To do so, the wearer must cast the spell on the guardian. The spell has no effect but is stored within the guardian. When commanded to do so by the wearer or when a situation arises that was predefined by the spellcaster, the guardian casts the stored spell with any parameters set by the original caster, requiring no components. When the spell is cast or a new spell is stored, any previously stored spell is lost."}],"actions":[{"name":"Multiattack","text":"The guardian makes two fist attacks."},{"name":"Fist","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"}],"reactions":[{"name":"Shield","text":"When a creature makes an attack against the wearer of the guardian''s amulet, the guardian grants a +2 bonus to the wearer''s AC if the guardian is within 5 feet of the wearer."}]}'),
    ('Shrieker', '/icons/monsters/_mono/S.svg', 'medium', 'plant', '{"name":"Shrieker","size":"medium","type":"plant","ac":5,"hp":13,"speed":{"walk":0},"abilities":{"str":1,"dex":1,"con":10,"int":1,"wis":3,"cha":1},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8","conditionImmunities":["Blinded","Deafened","Frightened"],"senses":["Blindsight 30 ft.","Passive Perception 6"],"languages":["--"],"traits":[{"name":"False Appearance","text":"While the shrieker remains motionless, it is indistinguishable from an ordinary fungus."}],"reactions":[{"name":"Shriek","text":"When bright light or a creature is within 30 feet of the shrieker, it emits a shriek audible within 300 feet of it. The shrieker continues to shriek until the disturbance moves out of range and for 1d4 of the shrieker''s turns afterward."}]}'),
    ('Silver Dragon Wyrmling', '/icons/monsters/_mono/S.svg', 'medium', 'dragon', '{"name":"Silver Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":45,"speed":{"walk":30,"fly":60},"abilities":{"str":19,"dex":10,"con":17,"int":12,"wis":11,"cha":15},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"6d8 + 18","saves":{"dex":2,"con":5,"wis":2,"cha":4},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Cold"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d10+4","damageType":"piercing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Cold Breath","text":"The dragon exhales an icy blast in a 15-foot cone. Each creature in that area must make a DC 13 Constitution saving throw, taking 18 (4d8) cold damage on a failed save, or half as much damage on a successful one.","saveDc":13,"saveAbility":"con"},{"name":"Paralyzing Breath","text":"The dragon exhales paralyzing gas in a 15-foot cone. Each creature in that area must succeed on a DC 13 Constitution saving throw or be paralyzed for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":13,"saveAbility":"con"}]}'),
    ('Skeleton', '/icons/monsters/_mono/S.svg', 'medium', 'undead', '{"name":"Skeleton","size":"medium","type":"undead","ac":13,"hp":13,"speed":{"walk":30},"abilities":{"str":10,"dex":14,"con":15,"int":6,"wis":8,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Armor Scraps","hitDice":"2d8 + 4","damageImmunities":["Poison"],"damageVulnerabilities":["Bludgeoning"],"conditionImmunities":["Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["Understands all languages it knew in life but can''t speak"],"actions":[{"name":"Shortsword","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Shortbow","text":"Ranged Weapon Attack: +4 to hit, range 80/320 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"range 80/320 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Solar', '/icons/monsters/_mono/S.svg', 'large', 'celestial', '{"name":"Solar","size":"large","type":"celestial","ac":21,"hp":243,"speed":{"walk":50,"fly":150},"abilities":{"str":26,"dex":22,"con":26,"int":25,"wis":25,"cha":30},"cr":"21","proficiencyBonus":7,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"18d10 + 144","saves":{"int":14,"wis":14,"cha":17},"skills":[{"name":"Perception","bonus":14}],"damageResistances":["Radiant","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Necrotic","Poison"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 24"],"languages":["All","Telepathy 120 ft."],"traits":[{"name":"Angelic Weapons","text":"The solar''s weapon attacks are magical. When the solar hits with any weapon, the weapon deals an extra 6d8 radiant damage (included in the attack)."},{"name":"Divine Awareness","text":"The solar knows if it hears a lie."},{"name":"Innate Spellcasting","text":"The solar''s spellcasting ability is Charisma (spell save DC 25). It can innately cast the following spells, requiring no material components:"},{"name":"Magic Resistance","text":"The solar has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The solar makes two greatsword attacks."},{"name":"Greatsword","text":"Melee Weapon Attack: +15 to hit, reach 5 ft., one target. Hit: 22 (4d6 + 8) slashing damage plus 27 (6d8) radiant damage.","attackBonus":15,"reach":"5 ft","damage":"4d6+8","damageType":"slashing"},{"name":"Slaying Longbow","text":"Ranged Weapon Attack: +13 to hit, range 150/600 ft., one target. Hit: 15 (2d8 + 6) piercing damage plus 27 (6d8) radiant damage. If the target is a creature that has 100 hit points or fewer, it must succeed on a DC 15 Constitution saving throw or die.","attackBonus":13,"reach":"range 150/600 ft","damage":"2d8+6","damageType":"piercing","saveDc":15,"saveAbility":"con"},{"name":"Flying Sword","text":"The solar releases its greatsword to hover magically in an unoccupied space within 5 feet of it. If the solar can see the sword, the solar can mentally command it as a bonus action to fly up to 50 feet and either make one attack against a target or return to the solar''s hands. If the hovering sword is targeted by any effect, the solar is considered to be holding it. The hovering sword falls if the solar dies."},{"name":"Healing Touch (4/Day)","text":"The solar touches another creature. The target magically regains 40 (8d8 + 4) hit points and is freed from any curse, disease, poison, blindness, or deafness."}],"legendaryActions":[{"name":"Teleport","text":"The solar magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."},{"name":"Searing Burst (Costs 2 Actions)","text":"The solar emits magical, divine energy. Each creature of its choice in a 10-foot radius must make a DC 23 Dexterity saving throw, taking 14 (4d6) fire damage plus 14 (4d6) radiant damage on a failed save, or half as much damage on a successful one."},{"name":"Blinding Gaze (Costs 3 Actions)","text":"The solar targets one creature it can see within 30 feet of it. If the target can see it, the target must succeed on a DC 15 Constitution saving throw or be blinded until magic such as the lesser restoration spell removes the blindness."}],"legendaryCount":3}'),
    ('Spectator', '/icons/monsters/_mono/S.svg', 'medium', 'aberration', '{"name":"Spectator","size":"medium","type":"aberration","ac":14,"hp":39,"speed":{"walk":0,"fly":30,"hover":true},"abilities":{"str":8,"dex":14,"con":14,"int":13,"wis":14,"cha":11},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful neutral","hitDice":"6d8 + 12","skills":[{"name":"Perception","bonus":6}],"conditionImmunities":["Prone"],"senses":["Darkvision 120 ft.","Passive Perception 16"],"languages":["Deep Speech","Telepathy 120 ft.","Undercommon"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 2 (1d6 − 1) piercing damage.","attackBonus":1,"reach":"5 ft"},{"name":"Eye Rays","text":"The spectator shoots up to two of the following magical eye rays at one or two creatures it can see within 90 feet of it. It can use each ray only once on a turn."},{"name":"Create Food and Water","text":"The spectator magically creates enough food and water to sustain itself for 24 hours."}],"reactions":[{"name":"Spell Reflection","text":"If the spectator makes a successful saving throw against a spell, or a spell attack misses it, the spectator can choose another creature (including the spellcaster) it can see within 30 feet of it. The spell targets the chosen creature instead of the spectator. If the spell forced a saving throw, the chosen creature makes its own save. If the spell was an attack, the attack roll is rerolled against the chosen creature."}]}'),
    ('Specter', '/icons/monsters/_mono/S.svg', 'medium', 'undead', '{"name":"Specter","size":"medium","type":"undead","ac":12,"hp":22,"speed":{"walk":0,"fly":50,"hover":true},"abilities":{"str":1,"dex":14,"con":11,"int":10,"wis":10,"cha":11},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"5d8","damageResistances":["Acid","Cold","Fire","Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Necrotic","Poison"],"conditionImmunities":["Charmed","Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Understands all languages it knew in life but can''t speak"],"traits":[{"name":"Incorporeal Movement","text":"The specter can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object."},{"name":"Sunlight Sensitivity","text":"While in sunlight, the specter has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Life Drain","text":"Melee Spell Attack: +4 to hit, reach 5 ft., one creature. Hit: 10 (3d6) necrotic damage. The target must succeed on a DC 10 Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the creature finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","attackBonus":4,"reach":"5 ft","damage":"3d6","damageType":"necrotic","saveDc":10,"saveAbility":"con"}]}'),
    ('Spider', '/icons/monsters/_mono/S.svg', 'tiny', 'beast', '{"name":"Spider","size":"tiny","type":"beast","ac":12,"hp":1,"speed":{"walk":20,"climb":20},"abilities":{"str":2,"dex":14,"con":8,"int":1,"wis":10,"cha":2},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Stealth","bonus":4}],"senses":["Darkvision 30 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Spider Climb","text":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","text":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","text":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 1 piercing damage, and the target must succeed on a DC 9 Constitution saving throw or take 2 (1d4) poison damage.","attackBonus":4,"reach":"5 ft","damage":"1d4","damageType":"poison","saveDc":9,"saveAbility":"con"}]}'),
    ('Spirit Naga', '/icons/monsters/_mono/S.svg', 'large', 'monstrosity', '{"name":"Spirit Naga","size":"large","type":"monstrosity","ac":15,"hp":75,"speed":{"walk":40},"abilities":{"str":18,"dex":17,"con":14,"int":16,"wis":15,"cha":16},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"10d10 + 20","saves":{"dex":6,"con":5,"wis":5,"cha":6},"damageImmunities":["Poison"],"conditionImmunities":["Charmed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Abyssal","Common"],"traits":[{"name":"Rejuvenation","text":"If it dies, the naga returns to life in 1d6 days and regains all its hit points. Only a wish spell can prevent this trait from functioning."},{"name":"Spellcasting","text":"The naga is a 10th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 14, +6 to hit with spell attacks), and it needs only verbal components to cast its spells. It has the following wizard spells prepared:"}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one creature. Hit: 7 (1d6 + 4) piercing damage, and the target must make a DC 13 Constitution saving throw, taking 31 (7d8) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":7,"reach":"10 ft","damage":"1d6+4","damageType":"piercing","saveDc":13,"saveAbility":"con"}]}'),
    ('Sprite', '/icons/monsters/_mono/S.svg', 'tiny', 'fey', '{"name":"Sprite","size":"tiny","type":"fey","ac":15,"hp":2,"speed":{"walk":10,"fly":40},"abilities":{"str":3,"dex":18,"con":10,"int":14,"wis":13,"cha":11},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","acNote":"Leather Armor","hitDice":"1d4","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":8}],"senses":["Passive Perception 13"],"languages":["Common","Elvish","Sylvan"],"actions":[{"name":"Longsword","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","attackBonus":2,"reach":"5 ft"},{"name":"Shortbow","text":"Ranged Weapon Attack: +6 to hit, range 40/160 ft., one target. Hit: 1 piercing damage, and the target must succeed on a DC 10 Constitution saving throw or become poisoned for 1 minute. If its saving throw result is 5 or lower, the poisoned target falls unconscious for the same duration, or until it takes damage or another creature takes an action to shake it awake.","attackBonus":6,"reach":"range 40/160 ft","saveDc":10,"saveAbility":"con"},{"name":"Heart Sight","text":"The sprite touches a creature and magically knows the creature''s current emotional state. If the target fails a DC 10 Charisma saving throw, the sprite also knows the creature''s alignment. Celestials, fiends, and undead automatically fail the saving throw.","saveDc":10,"saveAbility":"cha"},{"name":"Invisibility","text":"The sprite magically turns invisible until it attacks or casts a spell, or until its concentration ends (as if concentrating on a spell). Any equipment the sprite wears or carries is invisible with it."}]}'),
    ('Spy', '/icons/monsters/_mono/S.svg', 'medium', 'humanoid', '{"name":"Spy","size":"medium","type":"humanoid","ac":12,"hp":27,"speed":{"walk":30},"abilities":{"str":10,"dex":15,"con":10,"int":12,"wis":14,"cha":16},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","hitDice":"6d8","skills":[{"name":"Deception","bonus":5},{"name":"Insight","bonus":4},{"name":"Investigation","bonus":5},{"name":"Perception","bonus":6},{"name":"Persuasion","bonus":5},{"name":"Sleight of Hand","bonus":4},{"name":"Stealth","bonus":4}],"senses":["Passive Perception 16"],"languages":["Any two languages"],"traits":[{"name":"Cunning Action","text":"On each of its turns, the spy can use a bonus action to take the Dash, Disengage, or Hide action."},{"name":"Sneak Attack (1/Turn)","text":"The spy deals an extra 7 (2d6) damage when it hits a target with a weapon attack and has advantage on the attack roll, or when the target is within 5 feet of an ally of the spy that isn''t incapacitated and the spy doesn''t have disadvantage on the attack roll."}],"actions":[{"name":"Multiattack","text":"The spy makes two melee attacks."},{"name":"Shortsword","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Hand Crossbow","text":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"range 30/120 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Steam Mephit', '/icons/monsters/_mono/S.svg', 'small', 'elemental', '{"name":"Steam Mephit","size":"small","type":"elemental","ac":10,"hp":21,"speed":{"walk":30,"fly":30},"abilities":{"str":5,"dex":11,"con":10,"int":11,"wis":10,"cha":12},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"6d6","damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Aquan","Ignan"],"traits":[{"name":"Death Burst","text":"When the mephit dies, it explodes in a cloud of steam. Each creature within 5 feet of the mephit must succeed on a DC 10 Dexterity saving throw or take 4 (1d8) fire damage."},{"name":"Innate Spellcasting","text":"(1/Day). The mephit can innately cast blur, requiring no material components. Its innate spellcasting ability is Charisma."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 2 (1d4) slashing damage plus 2 (1d4) fire damage.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"slashing"},{"name":"Steam Breath (Recharge 6)","text":"The mephit exhales a 15- foot cone of scalding steam. Each creature in that area must succeed on a DC 10 Dexterity saving throw, taking 4 (1d8) fire damage on a failed save, or half as much damage on a successful one.","saveDc":10,"saveAbility":"dex"}]}'),
    ('Stirge', '/icons/monsters/_mono/S.svg', 'tiny', 'beast', '{"name":"Stirge","size":"tiny","type":"beast","ac":14,"hp":2,"speed":{"walk":10,"fly":40},"abilities":{"str":4,"dex":16,"con":11,"int":2,"wis":8,"cha":6},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"1d4","senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["--"],"actions":[{"name":"Blood Drain","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 5 (1d4 + 3) piercing damage, and the stirge attaches to the target. While attached, the stirge doesn''t attack. Instead, at the start of each of the stirge''s turns, the target loses 5 (1d4 + 3) hit points due to blood loss.","attackBonus":5,"reach":"5 ft","damage":"1d4+3","damageType":"piercing"}]}'),
    ('Stone Giant', '/icons/monsters/_mono/S.svg', 'huge', 'giant', '{"name":"Stone Giant","size":"huge","type":"giant","ac":17,"hp":126,"speed":{"walk":40},"abilities":{"str":23,"dex":15,"con":20,"int":10,"wis":12,"cha":9},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"11d12 + 55","saves":{"dex":5,"con":8,"wis":4},"skills":[{"name":"Athletics","bonus":12},{"name":"Perception","bonus":4}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Giant"],"traits":[{"name":"Stone Camouflage","text":"The giant has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"actions":[{"name":"Multiattack","text":"The giant makes two greatclub attacks. Greatclub. Melee Weapon Attack: +9 to hit, reach 15 ft., one target. Hit: 19 (3d8 + 6) bludgeoning damage.","attackBonus":9,"reach":"15 ft","damage":"3d8+6","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +9 to hit, range 60/240 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage. If the target is a creature, it must succeed on a DC 17 Strength saving throw or be knocked prone.","attackBonus":9,"reach":"range 60/240 ft","damage":"4d10+6","damageType":"bludgeoning","saveDc":17,"saveAbility":"str"}],"reactions":[{"name":"Rock Catching","text":"If a rock or similar object is hurled at the giant, the giant can, with a successful DC 10 Dexterity saving throw, catch the missile and take no bludgeoning damage from it."}]}'),
    ('Stone Golem', '/icons/monsters/_mono/S.svg', 'large', 'construct', '{"name":"Stone Golem","size":"large","type":"construct","ac":17,"hp":178,"speed":{"walk":30},"abilities":{"str":22,"dex":9,"con":20,"int":3,"wis":11,"cha":1},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"17d10 + 85","damageImmunities":["Poison","Psychic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Adamantine"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Immutable Form","text":"The golem is immune to any spell or effect that would alter its form."},{"name":"Magic Resistance","text":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The golem''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The golem makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 19 (3d8 + 6) bludgeoning damage.","attackBonus":10,"reach":"5 ft","damage":"3d8+6","damageType":"bludgeoning"},{"name":"Slow (Recharge 5–6)","text":"The golem targets one or more creatures it can see within 10 feet of it. Each target must make a DC 17 Wisdom saving throw against this magic. On a failed save, a target can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the target can take either an action or a bonus action on its turn, not both. These effects last for 1 minute. A target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":17,"saveAbility":"wis"}]}'),
    ('Storm Giant', '/icons/monsters/_mono/S.svg', 'huge', 'giant', '{"name":"Storm Giant","size":"huge","type":"giant","ac":16,"hp":230,"speed":{"walk":50,"swim":50},"abilities":{"str":29,"dex":14,"con":20,"int":16,"wis":18,"cha":18},"cr":"13","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Scale Mail","hitDice":"20d12 + 100","saves":{"str":14,"con":10,"wis":9,"cha":9},"skills":[{"name":"Arcana","bonus":8},{"name":"Athletics","bonus":14},{"name":"History","bonus":8},{"name":"Perception","bonus":9}],"damageResistances":["Cold"],"damageImmunities":["Lightning","Thunder"],"senses":["Passive Perception 19"],"languages":["Common","Giant"],"traits":[{"name":"Amphibious","text":"The giant can breathe air and water."},{"name":"Innate Spellcasting","text":"The giant''s innate spellcasting ability is Charisma (spell save DC 17). It can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"Multiattack","text":"The giant makes two greatsword attacks."},{"name":"Greatsword","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 30 (6d6 + 9) slashing damage.","attackBonus":14,"reach":"10 ft","damage":"6d6+9","damageType":"slashing"},{"name":"Rock","text":"Ranged Weapon Attack: +14 to hit, range 60/240 ft., one target. Hit: 35 (4d12 + 9) bludgeoning damage.","attackBonus":14,"reach":"range 60/240 ft","damage":"4d12+9","damageType":"bludgeoning"},{"name":"Lightning Strike (Recharge 5–6)","text":"The giant hurls a magical lightning bolt at a point it can see within 500 feet of it. Each creature within 10 feet of that point must make a DC 17 Dexterity saving throw, taking 54 (12d8) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":17,"saveAbility":"dex"}]}'),
    ('Succubus/Incubus', '/icons/monsters/_mono/S.svg', 'medium', 'fiend', '{"name":"Succubus/Incubus","size":"medium","type":"fiend","ac":15,"hp":66,"speed":{"walk":30,"fly":60},"abilities":{"str":8,"dex":17,"con":13,"int":15,"wis":12,"cha":20},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"12d8 + 12","skills":[{"name":"Deception","bonus":9},{"name":"Insight","bonus":5},{"name":"Perception","bonus":5},{"name":"Persuasion","bonus":9},{"name":"Stealth","bonus":7}],"damageResistances":["Cold","Fire","Lightning","Poison","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"senses":["Darkvision 60 ft.","Passive Perception 15"],"languages":["Abyssal","Common","Infernal","Telepathy 60 ft."],"traits":[{"name":"Telepathic Bond","text":"The fiend ignores the range restriction on its telepathy when communicating with a creature it has charmed. The two don''t even need to be on the same plane of existence."},{"name":"Shapechanger","text":"The fiend can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Without wings, the fiend loses its flying speed. Other than its size and speed, its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."}],"actions":[{"name":"Claw (Fiend Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Charm","text":"One humanoid the fiend can see within 30 feet of it must succeed on a DC 15 Wisdom saving throw or be magically charmed for 1 day. The charmed target obeys the fiend''s verbal or telepathic commands. If the target suffers any harm or receives a suicidal command, it can repeat the saving throw, ending the effect on a success. If the target successfully saves against the effect, or if the effect on it ends, the target is immune to this fiend''s Charm for the next 24 hours.","saveDc":15,"saveAbility":"wis"},{"name":"Draining Kiss","text":"The fiend kisses a creature charmed by it or a willing creature. The target must make a DC 15 Constitution saving throw against this magic, taking 32 (5d10 + 5) psychic damage on a failed save, or half as much damage on a successful one. The target''s hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","saveDc":15,"saveAbility":"con"},{"name":"Etherealness","text":"The fiend magically enters the Ethereal Plane from the Material Plane, or vice versa."}]}'),
    ('Swarm of Bats', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Bats","size":"medium","type":"beast","ac":12,"hp":22,"speed":{"walk":0,"fly":30},"abilities":{"str":5,"dex":15,"con":10,"int":2,"wis":12,"cha":4},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"5d8","damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Blindsight 60 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Echolocation","text":"The swarm can''t use its blindsight while deafened."},{"name":"Keen Hearing","text":"The swarm has advantage on Wisdom (Perception) checks that rely on hearing."},{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny bat. The swarm can''t regain hit points or gain temporary hit points."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 0 ft., one creature in the swarm''s space. Hit: 5 (2d4) piercing damage, or 2 (1d4) piercing damage if the swarm has half of its hit points or fewer.","attackBonus":4,"reach":"0 ft","damage":"2d4","damageType":"piercing"}]}'),
    ('Swarm of Insects', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Insects","size":"medium","type":"beast","ac":12,"hp":22,"speed":{"walk":20,"climb":20},"abilities":{"str":3,"dex":13,"con":10,"int":1,"wis":7,"cha":1},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d8","damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Blindsight 10 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 0 ft., one target in the swarm''s space. Hit: 10 (4d4) piercing damage, or 5 (2d4) piercing damage if the swarm has half of its hit points or fewer.","attackBonus":3,"reach":"0 ft","damage":"4d4","damageType":"piercing"}]}'),
    ('Swarm of Poisonous Snakes', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Poisonous Snakes","size":"medium","type":"beast","ac":14,"hp":36,"speed":{"walk":30,"swim":30},"abilities":{"str":8,"dex":18,"con":11,"int":1,"wis":10,"cha":3},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d8","damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Blindsight 10 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny snake. The swarm can''t regain hit points or gain temporary hit points."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 0 ft., one creature in the swarm''s space. Hit: 7 (2d6) piercing damage, or 3 (1d6) piercing damage if the swarm has half of its hit points or fewer. The target must make a DC 10 Constitution saving throw, taking 14 (4d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":6,"reach":"0 ft","damage":"2d6","damageType":"piercing","saveDc":10,"saveAbility":"con"}]}'),
    ('Swarm of Quippers', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Quippers","size":"medium","type":"beast","ac":13,"hp":28,"speed":{"walk":0,"swim":40},"abilities":{"str":13,"dex":16,"con":9,"int":1,"wis":7,"cha":2},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d8 - 8","damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Blood Frenzy","text":"The swarm has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny quipper. The swarm can''t regain hit points or gain temporary hit points."},{"name":"Water Breathing","text":"The swarm can breathe only underwater."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 0 ft., one creature in the swarm''s space. Hit: 14 (4d6) piercing damage, or 7 (2d6) piercing damage if the swarm has half of its hit points or fewer.","attackBonus":5,"reach":"0 ft","damage":"4d6","damageType":"piercing"}]}'),
    ('Swarm of Rats', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Rats","size":"medium","type":"beast","ac":10,"hp":24,"speed":{"walk":30},"abilities":{"str":9,"dex":11,"con":9,"int":2,"wis":10,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"7d8 - 7","damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Darkvision 30 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The swarm has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny rat. The swarm can''t regain hit points or gain temporary hit points."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 0 ft., one target in the swarm''s space. Hit: 7 (2d6) piercing damage, or 3 (1d6) piercing damage if the swarm has half of its hit points or fewer.","attackBonus":2,"reach":"0 ft","damage":"2d6","damageType":"piercing"}]}'),
    ('Swarm of Ravens', '/icons/monsters/_mono/S.svg', 'medium', 'beast', '{"name":"Swarm of Ravens","size":"medium","type":"beast","ac":12,"hp":24,"speed":{"walk":10,"fly":50},"abilities":{"str":6,"dex":14,"con":8,"int":3,"wis":12,"cha":6},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"7d8 - 7","skills":[{"name":"Perception","bonus":5}],"damageResistances":["Bludgeoning","Piercing","Slashing"],"conditionImmunities":["Charmed","Frightened","Grappled","Paralyzed","Petrified","Prone","Restrained","Stunned"],"senses":["Passive Perception 15"],"languages":["--"],"traits":[{"name":"Swarm","text":"The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny raven. The swarm can''t regain hit points or gain temporary hit points."}],"actions":[{"name":"Beaks","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target in the swarm''s space. Hit: 7 (2d6) piercing damage, or 3 (1d6) piercing damage if the swarm has half of its hit points or fewer.","attackBonus":4,"reach":"5 ft","damage":"2d6","damageType":"piercing"}]}'),
    ('Tarrasque', '/icons/monsters/_mono/T.svg', 'gargantuan', 'monstrosity', '{"name":"Tarrasque","size":"gargantuan","type":"monstrosity","ac":25,"hp":676,"speed":{"walk":40},"abilities":{"str":30,"dex":11,"con":30,"int":3,"wis":11,"cha":11},"cr":"30","proficiencyBonus":9,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"33d20 + 330","saves":{"int":5,"wis":9,"cha":9},"damageImmunities":["Fire","Poison","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Charmed","Frightened","Paralyzed","Poisoned"],"senses":["Blindsight 120 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Legendary Resistance (3/Day)","text":"If the tarrasque fails a saving throw, it can choose to succeed instead."},{"name":"Magic Resistance","text":"The tarrasque has advantage on saving throws against spells and other magical effects."},{"name":"Reflective Carapace","text":"Any time the tarrasque is targeted by a magic missile spell, a line spell, or a spell that requires a ranged attack roll, roll a d6. On a 1 to 5, the tarrasque is unaffected. On a 6, the tarrasque is unaffected, and the effect is reflected back at the caster as though it originated from the tarrasque, turning the caster into the target."},{"name":"Siege Monster","text":"The tarrasque deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","text":"The tarrasque can use its Frightful Presence. It then makes five attacks: one with its bite, two with its claws, one with its horns, and one with its tail. It can use its Swallow instead of its bite."},{"name":"Bite","text":"Melee Weapon Attack: +19 to hit, reach 10 ft., one target. Hit: 36 (4d12 + 10) piercing damage. If the target is a creature, it is grappled (escape DC 20). Until this grapple ends, the target is restrained, and the tarrasque can''t bite another target.","attackBonus":19,"reach":"10 ft","damage":"4d12+10","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +19 to hit, reach 15ft., one target. Hit: 28 (4d8 + 10) slashing damage.","attackBonus":19,"damage":"4d8+10","damageType":"slashing"},{"name":"Horns","text":"Melee Weapon Attack: +19 to hit, reach 10ft., one target. Hit: 32 (4d10 + 10) piercing damage.","attackBonus":19,"damage":"4d10+10","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +19 to hit, reach 20ft., one target. Hit: 24 (4d6 + 10) bludgeoning damage. If the target is a creature, it must succeed on a DC 20 Strength saving throw or be knocked prone.","attackBonus":19,"damage":"4d6+10","damageType":"bludgeoning","saveDc":20,"saveAbility":"str"},{"name":"Frightful Presence","text":"Each creature of the tarrasque''s choice within 120 feet of it and aware of it must succeed on a DC 17 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the tarrasque is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the tarrasque''s Frightful Presence for the next 24 hours.","saveDc":17,"saveAbility":"wis"},{"name":"Swallow","text":"The tarrasque makes one bite attack against a Large or smaller creature it is grappling. If the attack hits, the target takes the bite''s damage, the target is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the tarrasque, and it takes 56 (16d6) acid damage at the start of each of the tarrasque''s turns."}],"legendaryActions":[{"name":"Attack","text":"The tarrasque makes one claw attack or tail attack."},{"name":"Move","text":"The tarrasque moves up to half its speed."},{"name":"Chomp (Costs 2 Actions)","text":"The tarrasque makes one bite attack or uses its Swallow."}],"legendaryCount":3}'),
    ('Thug', '/icons/monsters/_mono/T.svg', 'medium', 'humanoid', '{"name":"Thug","size":"medium","type":"humanoid","ac":11,"hp":32,"speed":{"walk":30},"abilities":{"str":15,"dex":11,"con":14,"int":10,"wis":10,"cha":11},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Leather Armor","hitDice":"5d8 + 10","skills":[{"name":"Intimidation","bonus":2}],"senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Pack Tactics","text":"The thug has advantage on an attack roll against a creature if at least one of the thug''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Multiattack","text":"The thug makes two melee attacks."},{"name":"Mace","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) bludgeoning damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"bludgeoning"},{"name":"Heavy Crossbow","text":"Ranged Weapon Attack: +2 to hit, range 100/400 ft., one target. Hit: 5 (1d10) piercing damage.","attackBonus":2,"reach":"range 100/400 ft","damage":"1d10","damageType":"piercing"}]}'),
    ('Tiger', '/icons/monsters/_mono/T.svg', 'large', 'beast', '{"name":"Tiger","size":"large","type":"beast","ac":12,"hp":37,"speed":{"walk":40},"abilities":{"str":17,"dex":15,"con":14,"int":3,"wis":12,"cha":8},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"5d10 + 10","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":6}],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The tiger has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pounce","text":"If the tiger moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 13 Strength saving throw or be knocked prone. If the target is prone, the tiger can make one bite attack against it as a bonus action."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d10+3","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"slashing"}]}'),
    ('Treant', '/icons/monsters/_mono/T.svg', 'huge', 'plant', '{"name":"Treant","size":"huge","type":"plant","ac":16,"hp":138,"speed":{"walk":30},"abilities":{"str":23,"dex":8,"con":21,"int":12,"wis":16,"cha":12},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"12d12 + 60","damageResistances":["Bludgeoning","Piercing"],"damageVulnerabilities":["Fire"],"senses":["Passive Perception 13"],"languages":["Common","Druidic","Elvish","Sylvan"],"traits":[{"name":"False Appearance","text":"While the treant remains motionless, it is indistinguishable from a normal tree."},{"name":"Siege Monster","text":"The treant deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","text":"The treant makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 16 (3d6 + 6) bludgeoning damage.","attackBonus":10,"reach":"5 ft","damage":"3d6+6","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +10 to hit, range 60/180 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage.","attackBonus":10,"reach":"range 60/180 ft","damage":"4d10+6","damageType":"bludgeoning"},{"name":"Animate Trees (1/Day)","text":"The treant magically animates one or two trees it can see within 60 feet of it. These trees have the same statistics as a treant, except they have Intelligence and Charisma scores of 1, they can''t speak, and they have only the Slam action option. An animated tree acts as an ally of the treant. The tree remains animate for 1 day or until it dies; until the treant dies or is more than 120 feet from the tree; or until the treant takes a bonus action to turn it back into an inanimate tree. The tree then takes root if possible."}]}'),
    ('Tribal Warrior', '/icons/monsters/_mono/T.svg', 'medium', 'humanoid', '{"name":"Tribal Warrior","size":"medium","type":"humanoid","ac":12,"hp":11,"speed":{"walk":30},"abilities":{"str":13,"dex":11,"con":12,"int":8,"wis":11,"cha":8},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Hide Armor","hitDice":"2d8 + 2","senses":["Passive Perception 10"],"languages":["Any one language"],"traits":[{"name":"Pack Tactics","text":"The warrior has advantage on an attack roll against a creature if at least one of the warrior''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Spear","text":"Melee or Ranged Weapon Attack: +3 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d6 + 1) piercing damage, or 5 (1d8 + 1) piercing damage if used with two hands to make a melee attack.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"}]}'),
    ('Triceratops', '/icons/monsters/_mono/T.svg', 'huge', 'beast', '{"name":"Triceratops","size":"huge","type":"beast","ac":13,"hp":95,"speed":{"walk":50},"abilities":{"str":22,"dex":9,"con":17,"int":2,"wis":11,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"10d12 + 30","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Trampling Charge","text":"If the triceratops moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 13 Strength saving throw or be knocked prone. If the target is prone, the triceratops can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 24 (4d8 + 6) piercing damage.","attackBonus":9,"reach":"5 ft","damage":"4d8+6","damageType":"piercing"},{"name":"Stomp","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one prone creature. Hit: 22 (3d10 + 6) bludgeoning damage.","attackBonus":9,"reach":"5 ft","damage":"3d10+6","damageType":"bludgeoning"}]}'),
    ('Troll', '/icons/monsters/_mono/T.svg', 'large', 'giant', '{"name":"Troll","size":"large","type":"giant","ac":15,"hp":84,"speed":{"walk":30},"abilities":{"str":18,"dex":13,"con":20,"int":7,"wis":9,"cha":7},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"8d10 + 40","skills":[{"name":"Perception","bonus":2}],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Giant"],"traits":[{"name":"Keen Smell","text":"The troll has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Regeneration","text":"The troll regains 10 hit points at the start of its turn. If the troll takes acid or fire damage, this trait doesn''t function at the start of the troll''s next turn. The troll dies only if it starts its turn with 0 hit points and doesn''t regenerate."}],"actions":[{"name":"Multiattack","text":"The troll makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"1d6+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"}]}'),
    ('Twig Blight', '/icons/monsters/_mono/T.svg', 'small', 'plant', '{"name":"Twig Blight","size":"small","type":"plant","ac":13,"hp":4,"speed":{"walk":20},"abilities":{"str":6,"dex":13,"con":12,"int":4,"wis":8,"cha":3},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"1d6 + 1","skills":[{"name":"Stealth","bonus":3}],"damageVulnerabilities":["Fire"],"conditionImmunities":["Blinded","Deafened"],"senses":["Blindsight 60 ft. (blind beyond this radius)","Passive Perception 9"],"languages":["Common understands but canât speak"],"traits":[{"name":"False Appearance","text":"While the blight remains motionless, it is indistinguishable from a dead shrub."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"piercing"}]}'),
    ('Tyrannosaurus Rex', '/icons/monsters/_mono/T.svg', 'huge', 'beast', '{"name":"Tyrannosaurus Rex","size":"huge","type":"beast","ac":13,"hp":136,"speed":{"walk":50},"abilities":{"str":25,"dex":10,"con":19,"int":2,"wis":12,"cha":9},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"13d12 + 52","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"actions":[{"name":"Multiattack","text":"The tyrannosaurus makes two attacks: one with its bite and one with its tail. It can''t make both attacks against the same target."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 33 (4d12 + 7) piercing damage. If the target is a Medium or smaller creature, it is grappled (escape DC 17). Until this grapple ends, the target is restrained, and the tyrannosaurus can''t bite another target.","attackBonus":10,"reach":"10 ft","damage":"4d12+7","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 20 (3d8 + 7) bludgeoning damage.","attackBonus":10,"reach":"10 ft","damage":"3d8+7","damageType":"bludgeoning"}]}'),
    ('Unicorn', '/icons/monsters/_mono/U.svg', 'large', 'celestial', '{"name":"Unicorn","size":"large","type":"celestial","ac":12,"hp":67,"speed":{"walk":50},"abilities":{"str":18,"dex":14,"con":15,"int":11,"wis":17,"cha":16},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","hitDice":"9d10 + 18","damageImmunities":["Poison"],"conditionImmunities":["Charmed","Paralyzed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["Celestial","Elvish","Sylvan","Telepathy 60 ft."],"traits":[{"name":"Charge","text":"If the unicorn moves at least 20 feet straight toward a target and then hits it with a horn attack on the same turn, the target takes an extra 9 (2d8) piercing damage. If the target is a creature, it must succeed on a DC 15 Strength saving throw or be knocked prone."},{"name":"Innate Spellcasting","text":"The unicorn''s innate spellcasting ability is Charisma (spell save DC 14). The unicorn can innately cast the following spells, requiring no components:"},{"name":"Magic Resistance","text":"The unicorn has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The unicorn''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The unicorn makes two attacks: one with its hooves and one with its horn."},{"name":"Hooves","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"},{"name":"Horn","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"1d8+4","damageType":"piercing"},{"name":"Healing Touch (3/Day)","text":"The unicorn touches another creature with its horn. The target magically regains 11 (2d8 + 2) hit points. In addition, the touch removes all diseases and neutralizes all poisons afflicting the target."},{"name":"Teleport (1/Day)","text":"The unicorn magically teleports itself and up to three willing creatures it can see within 5 feet of it, along with any equipment they are wearing or carrying, to a location the unicorn is familiar with, up to 1 mile away."}],"legendaryActions":[{"name":"Hooves","text":"The unicorn makes one attack with its hooves."},{"name":"Shimmering Shield (Costs 2 Actions)","text":"The unicorn creates a shimmering, magical field around itself or another creature it can see within 60 feet of it. The target gains a +2 bonus to AC until the end of the unicorn''s next turn."},{"name":"Heal Self (Costs 3 Actions)","text":"The unicorn magically regains 11 (2d8 + 2) hit points."}],"legendaryCount":3}'),
    ('Vampire', '/icons/monsters/_mono/V.svg', 'medium', 'undead', '{"name":"Vampire","size":"medium","type":"undead","ac":16,"hp":144,"speed":{"walk":30},"abilities":{"str":18,"dex":18,"con":18,"int":17,"wis":15,"cha":18},"cr":"13","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"17d8 + 68","saves":{"dex":9,"wis":7,"cha":9},"skills":[{"name":"Perception","bonus":7},{"name":"Stealth","bonus":9}],"damageResistances":["Necrotic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"senses":["Darkvision 120 ft.","Passive Perception 17"],"languages":["the languages it knew in life"],"traits":[{"name":"Shapechanger","text":"If the vampire isn''t in sunlight or running water, it can use its action to polymorph into a Tiny bat or a Medium cloud of mist, or back into its true form."},{"name":"Legendary Resistance (3/Day)","text":"If the vampire fails a saving throw, it can choose to succeed instead."},{"name":"Misty Escape","text":"When it drops to 0 hit points outside its resting place, the vampire transforms into a cloud of mist (as in the Shapechanger trait) instead of falling unconscious, provided that it isn''t in sunlight or running water. If it can''t transform, it is destroyed."},{"name":"Regeneration","text":"The vampire regains 20 hit points at the start of its turn if it has at least 1 hit point and isn''t in sunlight or running water. If the vampire takes radiant damage or damage from holy water, this trait doesn''t function at the start of the vampire''s next turn."},{"name":"Spider Climb","text":"The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Vampire Weaknesses","text":"The vampire has the following flaws:"}],"actions":[{"name":"Multiattack. (Vampire Form Only)","text":"The vampire makes two attacks, only one of which can be a bite attack."},{"name":"Unarmed Strike (Vampire Form Only)","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one creature. Hit: 8 (1d8 + 4) bludgeoning damage. Instead of dealing damage, the vampire can grapple the target (escape DC 18).","attackBonus":9,"reach":"5 ft","damage":"1d8+4","damageType":"bludgeoning"},{"name":"Bite. (Bat or Vampire Form Only)","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one willing creature, or a creature that is grappled by the vampire, incapacitated, or restrained. Hit: 7 (1d6 + 4) piercing damage plus 10 (3d6) necrotic damage. The target''s hit point maximum is reduced by an amount equal to the necrotic damage taken, and the vampire regains hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0. A humanoid slain in this way and then buried in the ground rises the following night as a vampire spawn under the vampire''s control.","attackBonus":9,"reach":"5 ft","damage":"1d6+4","damageType":"piercing"},{"name":"Charm","text":"The vampire targets one humanoid it can see within 30 feet of it. If the target can see the vampire, the target must succeed on a DC 17 Wisdom saving throw against this magic or be charmed by the vampire. The charmed target regards the vampire as a trusted friend to be heeded and protected. Although the target isn''t under the vampire''s control, it takes the vampire''s requests or actions in the most favorable way it can, and it is a willing target for the vampire''s bite attack.","saveDc":17,"saveAbility":"wis"},{"name":"Children of the Night (1/Day)","text":"The vampire magically calls 2d4 swarms of bats or rats (swarm of bats, swarm of rats), provided that the sun isn''t up. While outdoors, the vampire can call 3d6 wolves (wolf) instead. The called creatures arrive in 1d4 rounds, acting as allies of the vampire and obeying its spoken commands. The beasts remain for 1 hour, until the vampire dies, or until the vampire dismisses them as a bonus action."}],"legendaryActions":[{"name":"Move","text":"The vampire moves up to its speed without provoking opportunity attacks."},{"name":"Unarmed Strike","text":"The vampire makes one unarmed strike."},{"name":"Bite","text":"(Costs 2 Actions). The vampire makes one bite attack."}],"legendaryCount":3}'),
    ('Vampire Spawn', '/icons/monsters/_mono/V.svg', 'medium', 'undead', '{"name":"Vampire Spawn","size":"medium","type":"undead","ac":15,"hp":82,"speed":{"walk":30},"abilities":{"str":16,"dex":16,"con":16,"int":11,"wis":10,"cha":12},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"11d8 + 33","saves":{"dex":6,"wis":3},"skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":6}],"damageResistances":["Necrotic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["the languages it knew in life"],"traits":[{"name":"Regeneration","text":"The vampire regains 10 hit points at the start of its turn if it has at least 1 hit point and isn''t in sunlight or running water. If the vampire takes radiant damage or damage from holy water, this trait doesn''t function at the start of the vampire''s next turn."},{"name":"Spider Climb","text":"The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Vampire Weaknesses","text":"The vampire has the following flaws:"}],"actions":[{"name":"Multiattack","text":"The vampire makes two attacks, only one of which can be a bite attack."},{"name":"Claws","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 8 (2d4 + 3) slashing damage. Instead of dealing damage, the vampire can grapple the target (escape DC 13).","attackBonus":6,"reach":"5 ft","damage":"2d4+3","damageType":"slashing"},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one willing creature, or a creature that is grappled by the vampire, incapacitated, or restrained. Hit: 6 (1d6 + 3) piercing damage plus 7 (2d6) necrotic damage. The target''s hit point maximum is reduced by an amount equal to the necrotic damage taken, and the vampire regains hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","attackBonus":6,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"}]}'),
    ('Veteran', '/icons/monsters/_mono/V.svg', 'medium', 'humanoid', '{"name":"Veteran","size":"medium","type":"humanoid","ac":17,"hp":58,"speed":{"walk":30},"abilities":{"str":16,"dex":13,"con":14,"int":10,"wis":11,"cha":10},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Splint","hitDice":"9d8 + 18","skills":[{"name":"Athletics","bonus":5},{"name":"Perception","bonus":2}],"senses":["Passive Perception 12"],"languages":["Any one language (usually Common)"],"actions":[{"name":"Multiattack","text":"The veteran makes two longsword attacks. If it has a shortsword drawn, it can also make a shortsword attack."},{"name":"Longsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage, or 8 (1d10 + 3) slashing damage if used with two hands.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"slashing"},{"name":"Shortsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"},{"name":"Heavy Crossbow","text":"Ranged Weapon Attack: +3 to hit, range 100/400 ft., one target. Hit: 6 (1d10 + 1) piercing damage.","attackBonus":3,"reach":"range 100/400 ft","damage":"1d10+1","damageType":"piercing"}]}'),
    ('Violet Fungus', '/icons/monsters/_mono/V.svg', 'medium', 'plant', '{"name":"Violet Fungus","size":"medium","type":"plant","ac":5,"hp":18,"speed":{"walk":5},"abilities":{"str":3,"dex":1,"con":10,"int":1,"wis":3,"cha":1},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"4d8","conditionImmunities":["Blinded","Deafened","Frightened"],"senses":["Blindsight 30 ft.","Passive Perception 6"],"languages":["--"],"traits":[{"name":"False Appearance","text":"While the violet fungus remains motionless, it is indistinguishable from an ordinary fungus."}],"actions":[{"name":"Multiattack","text":"The fungus makes 1d4 Rotting Touch attacks."},{"name":"Rotting Touch","text":"Melee Weapon Attack: +2 to hit, reach 10 ft., one creature. Hit: 4 (1d8) necrotic damage.","attackBonus":2,"reach":"10 ft","damage":"1d8","damageType":"necrotic"}]}'),
    ('Vrock', '/icons/monsters/_mono/V.svg', 'large', 'fiend', '{"name":"Vrock","size":"large","type":"fiend","ac":15,"hp":104,"speed":{"walk":40,"fly":60},"abilities":{"str":17,"dex":15,"con":18,"int":8,"wis":13,"cha":8},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"11d10 + 44","saves":{"dex":5,"wis":4,"cha":2},"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Magic Resistance","text":"The vrock has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The vrock makes two attacks: one with its beak and one with its talons."},{"name":"Beak","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+3","damageType":"piercing"},{"name":"Talons","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 14 (2d10 + 3) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d10+3","damageType":"slashing"},{"name":"Spores (Recharge 6)","text":"A 15­-foot­-radius cloud of toxic spores extends out from the vrock. The spores spread around corners. Each creature in that area must succeed on a DC 14 Constitution saving throw or become poisoned. While poisoned in this way, a target takes 5 (1d10) poison damage at the start of each of its turns. A target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Emptying a vial of holy water on the target also ends the effect on it.","saveDc":14,"saveAbility":"con"},{"name":"Stunning Screech (1/Day)","text":"The vrock emits a horrific screech. Each creature within 20 feet of it that can hear it and that isn''t a demon must succeed on a DC 14 Constitution saving throw or be stunned until the end of the vrock''s next turn.","saveDc":14,"saveAbility":"con"}]}'),
    ('Vulture', '/icons/monsters/_mono/V.svg', 'medium', 'beast', '{"name":"Vulture","size":"medium","type":"beast","ac":10,"hp":5,"speed":{"walk":10,"fly":50},"abilities":{"str":7,"dex":10,"con":13,"int":2,"wis":12,"cha":4},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d8 + 1","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Sight and Smell","text":"The vulture has advantage on Wisdom (Perception) checks that rely on sight or smell."},{"name":"Pack Tactics","text":"The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Beak","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) piercing damage.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"piercing"}]}'),
    ('Warhorse', '/icons/monsters/_mono/W.svg', 'large', 'beast', '{"name":"Warhorse","size":"large","type":"beast","ac":11,"hp":19,"speed":{"walk":60},"abilities":{"str":18,"dex":12,"con":13,"int":2,"wis":12,"cha":7},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d10 + 3","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Trampling Charge","text":"If the horse moves at least 20 feet straight toward a creature and then hits it with a hooves attack on the same turn, that target must succeed on a DC 14 Strength saving throw or be knocked prone. If the target is prone, the horse can make another attack with its hooves against it as a bonus action."}],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"}]}'),
    ('Warhorse Skeleton', '/icons/monsters/_mono/W.svg', 'large', 'undead', '{"name":"Warhorse Skeleton","size":"large","type":"undead","ac":13,"hp":22,"speed":{"walk":60},"abilities":{"str":18,"dex":12,"con":15,"int":2,"wis":8,"cha":5},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Barding Scraps","hitDice":"3d10 + 6","damageImmunities":["Poison"],"damageVulnerabilities":["Bludgeoning"],"conditionImmunities":["Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["--"],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"}]}'),
    ('Water Elemental', '/icons/monsters/_mono/W.svg', 'large', 'elemental', '{"name":"Water Elemental","size":"large","type":"elemental","ac":14,"hp":114,"speed":{"walk":30,"swim":90},"abilities":{"str":18,"dex":14,"con":18,"int":5,"wis":10,"cha":8},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"12d10 + 48","damageResistances":["Acid","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Aquan"],"traits":[{"name":"Water Form","text":"The elemental can enter a hostile creature''s space and stop there. It can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Freeze","text":"If the elemental takes cold damage, it partially freezes; its speed is reduced by 20 feet until the end of its next turn."}],"actions":[{"name":"Multiattack","text":"The elemental makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"},{"name":"Whelm (Recharge 4–6)","text":"Each creature in the elemental''s space must make a DC 15 Strength saving throw. On a failure, a target takes 13 (2d8 + 4) bludgeoning damage. If it is Large or smaller, it is also grappled (escape DC 14). Until this grapple ends, the target is restrained and unable to breathe unless it can breathe water. If the saving throw is successful, the target is pushed out of the elemental''s space.","saveDc":15,"saveAbility":"str"}]}'),
    ('Weasel', '/icons/monsters/_mono/W.svg', 'tiny', 'beast', '{"name":"Weasel","size":"tiny","type":"beast","ac":13,"hp":1,"speed":{"walk":30},"abilities":{"str":3,"dex":16,"con":8,"int":2,"wis":12,"cha":3},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":5}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The weasel has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":5,"reach":"5 ft"}]}'),
    ('Werebear', '/icons/monsters/_mono/W.svg', 'medium', 'humanoid', '{"name":"Werebear","size":"medium","type":"humanoid","ac":10,"hp":135,"speed":{"walk":40,"climb":30},"abilities":{"str":19,"dex":10,"con":17,"int":11,"wis":12,"cha":12},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","hitDice":"18d8 + 54","skills":[{"name":"Perception","bonus":7}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"senses":["Passive Perception 17"],"languages":["Common (can''t speak in bear form)"],"traits":[{"name":"Shapechanger","text":"The werebear can use its action to polymorph into a Large bear-humanoid hybrid or into a Large bear, or back into its true form, which is humanoid. Its statistics, other than its size and AC, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Keen Smell","text":"The werebear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","text":"In bear form, the werebear makes two claw attacks. In humanoid form, it makes two greataxe attacks. In hybrid form, it can attack like a bear or a humanoid."},{"name":"Bite (Bear or Hybrid Form Only)","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 15 (2d10 + 4) piercing damage. If the target is a humanoid, it must succeed on a DC 14 Constitution saving throw or be cursed with werebear lycanthropy.","attackBonus":7,"reach":"5 ft","damage":"2d10+4","damageType":"piercing","saveDc":14,"saveAbility":"con"},{"name":"Claw (Bear or Hybrid Form Only)","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"},{"name":"Greataxe (Humanoid or Hybrid Form Only)","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 10 (1d12 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"1d12+4","damageType":"slashing"}]}'),
    ('Wereboar', '/icons/monsters/_mono/W.svg', 'medium', 'humanoid', '{"name":"Wereboar","size":"medium","type":"humanoid","ac":10,"hp":78,"speed":{"walk":40},"abilities":{"str":17,"dex":10,"con":15,"int":10,"wis":11,"cha":8},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"12d8 + 24","skills":[{"name":"Perception","bonus":2}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"senses":["Passive Perception 12"],"languages":["Common (can''t speak in boar form)"],"traits":[{"name":"Shapechanger","text":"The wereboar can use its action to polymorph into a boar-humanoid hybrid or into a boar, or back into its true form, which is humanoid. Its statistics, other than its AC, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Charge (Boar or Hybrid Form Only)","text":"If the wereboar moves at least 15 feet straight toward a target and then hits it with its tusks on the same turn, the target takes an extra 7 (2d6) slashing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone."},{"name":"Relentless (Recharges after a Short or Long Rest)","text":"If the wereboar takes 14 damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead."}],"actions":[{"name":"Multiattack (Humanoid or Hybrid Form Only)","text":"The wereboar makes two attacks, only one of which can be with its tusks."},{"name":"Maul (Humanoid or Hybrid Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"bludgeoning"},{"name":"Tusks (Boar or Hybrid Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage. If the target is a humanoid, it must succeed on a DC 12 Constitution saving throw or be cursed with wereboar lycanthropy.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing","saveDc":12,"saveAbility":"con"}]}'),
    ('Wererat', '/icons/monsters/_mono/W.svg', 'medium', 'humanoid', '{"name":"Wererat","size":"medium","type":"humanoid","ac":12,"hp":33,"speed":{"walk":30},"abilities":{"str":10,"dex":15,"con":12,"int":11,"wis":10,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","hitDice":"6d8 + 6","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":4}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Common (can''t speak in rat form)"],"traits":[{"name":"Shapechanger","text":"The wererat can use its action to polymorph into a rat-humanoid hybrid or into a giant rat, or back into its true form, which is humanoid. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Keen Smell","text":"The wererat has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack (Humanoid or Hybrid Form Only)","text":"The wererat makes two attacks, only one of which can be a bite."},{"name":"Bite (Rat or Hybrid Form Only)","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage. If the target is a humanoid, it must succeed on a DC 11 Constitution saving throw or be cursed with wererat lycanthropy.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing","saveDc":11,"saveAbility":"con"},{"name":"Shortsword (Humanoid or Hybrid Form Only)","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Hand Crossbow (Humanoid or Hybrid Form Only)","text":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"range 30/120 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Weretiger', '/icons/monsters/_mono/W.svg', 'medium', 'humanoid', '{"name":"Weretiger","size":"medium","type":"humanoid","ac":12,"hp":120,"speed":{"walk":40},"abilities":{"str":17,"dex":15,"con":16,"int":10,"wis":13,"cha":11},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"16d8 + 48","skills":[{"name":"Perception","bonus":5},{"name":"Stealth","bonus":4}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"senses":["Darkvision 60 ft.","Passive Perception 15"],"languages":["Common (can''t speak in tiger form)"],"traits":[{"name":"Shapechanger","text":"The weretiger can use its action to polymorph into a tiger-humanoid hybrid or into a tiger, or back into its true form, which is humanoid. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Keen Hearing and Smell","text":"The weretiger has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pounce (Tiger or Hybrid Form Only)","text":"If the weretiger moves at least 15 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 14 Strength saving throw or be knocked prone. If the target is prone, the weretiger can make one bite attack against it as a bonus action."}],"actions":[{"name":"Multiattack (Humanoid or Hybrid Form Only)","text":"In humanoid form, the weretiger makes two scimitar attacks or two longbow attacks. In hybrid form, it can attack like a humanoid or make two claw attacks."},{"name":"Bite (Tiger or Hybrid Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage. If the target is a humanoid, it must succeed on a DC 13 Constitution saving throw or be cursed with weretiger lycanthropy.","attackBonus":5,"reach":"5 ft","damage":"1d10+3","damageType":"piercing","saveDc":13,"saveAbility":"con"},{"name":"Claw (Tiger or Hybrid Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"slashing"},{"name":"Scimitar (Humanoid or Hybrid Form Only)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Longbow (Humanoid or Hybrid Form Only)","text":"Ranged Weapon Attack: +4 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"range 150/600 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Werewolf', '/icons/monsters/_mono/W.svg', 'medium', 'humanoid', '{"name":"Werewolf","size":"medium","type":"humanoid","ac":11,"hp":58,"speed":{"walk":40},"abilities":{"str":15,"dex":13,"con":14,"int":10,"wis":11,"cha":10},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"9d8 + 18","skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":3}],"damageImmunities":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"senses":["Passive Perception 14"],"languages":["Common (can''t speak in wolf form)"],"traits":[{"name":"Shapechanger","text":"The werewolf can use its action to polymorph into a wolf-humanoid hybrid or into a wolf, or back into its true form, which is humanoid. Its statistics, other than its AC, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Keen Hearing and Smell","text":"The werewolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Multiattack. (Humanoid or Hybrid Form Only)","text":"The werewolf makes two attacks: one with its bite and one with its claws or spear."},{"name":"Bite (Wolf or Hybrid Form Only)","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage. If the target is a humanoid, it must succeed on a DC 12 Constitution saving throw or be cursed with werewolf lycanthropy.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing","saveDc":12,"saveAbility":"con"},{"name":"Claws. (Hybrid Form Only)","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (2d4 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"slashing"},{"name":"Spear (Humanoid Form Only)","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 20/60 ft., one creature. Hit: 5 (1d6 + 2) piercing damage, or 6 (1d8 + 2) piercing damage if used with two hands to make a melee attack.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('White Dragon Wyrmling', '/icons/monsters/_mono/W.svg', 'medium', 'dragon', '{"name":"White Dragon Wyrmling","size":"medium","type":"dragon","ac":16,"hp":32,"speed":{"walk":30,"burrow":15,"fly":60,"swim":30},"abilities":{"str":14,"dex":10,"con":14,"int":5,"wis":10,"cha":11},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"5d8 + 10","saves":{"dex":2,"con":4,"wis":2,"cha":2},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Cold"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 2 (1d4) cold damage.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Cold Breath (Recharge 5–6)","text":"The dragon exhales an icy blast of hail in a 15-foot cone. Each creature in that area must make a DC 12 Constitution saving throw, taking 22 (5d8) cold damage on a failed save, or half as much damage on a successful one.","saveDc":12,"saveAbility":"con"}]}'),
    ('Wight', '/icons/monsters/_mono/W.svg', 'medium', 'undead', '{"name":"Wight","size":"medium","type":"undead","ac":14,"hp":45,"speed":{"walk":30},"abilities":{"str":15,"dex":14,"con":16,"int":10,"wis":13,"cha":15},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Studded Leather","hitDice":"6d8 + 18","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"damageResistances":["Necrotic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Poison"],"conditionImmunities":["Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["The languages it knew in life"],"traits":[{"name":"Sunlight Sensitivity","text":"While in sunlight, the wight has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The wight makes two longsword attacks or two longbow attacks. It can use its Life Drain in place of one longsword attack."},{"name":"Life Drain","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) necrotic damage. The target must succeed on a DC 13 Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"necrotic","saveDc":13,"saveAbility":"con"},{"name":"Longsword","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) slashing damage, or 7 (1d10 + 2) slashing damage if used with two hands.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"slashing"},{"name":"Longbow","text":"Ranged Weapon Attack: +4 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"range 150/600 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Will-o''-Wisp', '/icons/monsters/_mono/W.svg', 'tiny', 'undead', '{"name":"Will-o''-Wisp","size":"tiny","type":"undead","ac":19,"hp":22,"speed":{"walk":0,"fly":50,"hover":true},"abilities":{"str":1,"dex":28,"con":10,"int":13,"wis":14,"cha":11},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"9d4","damageResistances":["Acid","Cold","Fire","Necrotic","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Lightning","Poison"],"conditionImmunities":["Exhaustion","Grappled","Paralyzed","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 120 ft.","Passive Perception 12"],"languages":["The languages it knew in life"],"traits":[{"name":"Consume Life","text":"As a bonus action, the will-o''-wisp can target one creature it can see within 5 feet of it that has 0 hit points and is still alive. The target must succeed on a DC 10 Constitution saving throw against this magic or die. If the target dies, the will-o''-wisp regains 10 (3d6) hit points."},{"name":"Ephemeral","text":"The will-o''-wisp can''t wear or carry anything."},{"name":"Incorporeal Movement","text":"The will-o''-wisp can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object."},{"name":"Variable Illumination","text":"The will-o''-wisp sheds bright light in a 5- to 20-foot radius and dim light for an additional number of feet equal to the chosen radius. The will-o''-wisp can alter the radius as a bonus action."}],"actions":[{"name":"Shock","text":"Melee Spell Attack: +4 to hit, reach 5 ft., one creature. Hit: 9 (2d8) lightning damage.","attackBonus":4,"reach":"5 ft","damage":"2d8","damageType":"lightning"},{"name":"Invisibility","text":"The will-o''-wisp and its light magically become invisible until it attacks or uses its Consume Life, or until its concentration ends (as if concentrating on a spell)."}]}'),
    ('Winter Wolf', '/icons/monsters/_mono/W.svg', 'large', 'monstrosity', '{"name":"Winter Wolf","size":"large","type":"monstrosity","ac":13,"hp":75,"speed":{"walk":50},"abilities":{"str":18,"dex":13,"con":14,"int":7,"wis":12,"cha":8},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"10d10 + 20","skills":[{"name":"Perception","bonus":5},{"name":"Stealth","bonus":3}],"damageImmunities":["Cold"],"senses":["Passive Perception 15"],"languages":["Common","Giant","Winter Wolf"],"traits":[{"name":"Keen Hearing and Smell","text":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"The wolf has advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally isn''t incapacitated."},{"name":"Snow Camouflage","text":"The wolf has advantage on Dexterity (Stealth) checks made to hide in snowy terrain."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) piercing damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be knocked prone.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"piercing","saveDc":14,"saveAbility":"str"},{"name":"Cold Breath (Recharge 5–6)","text":"The wolf exhales a blast of freezing wind in a 15-foot cone. Each creature in that area must make a DC 12 Dexterity saving throw, taking 18 (4d8) cold damage on a failed save, or half as much damage on a successful one.","saveDc":12,"saveAbility":"dex"}]}'),
    ('Wolf', '/icons/monsters/_mono/W.svg', 'medium', 'beast', '{"name":"Wolf","size":"medium","type":"beast","ac":13,"hp":11,"speed":{"walk":40},"abilities":{"str":12,"dex":15,"con":12,"int":3,"wis":12,"cha":6},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"2d8 + 2","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"The wolf has advantage on attack rolls against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) piercing damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"piercing","saveDc":11,"saveAbility":"str"}]}'),
    ('Worg', '/icons/monsters/_mono/W.svg', 'large', 'monstrosity', '{"name":"Worg","size":"large","type":"monstrosity","ac":13,"hp":26,"speed":{"walk":50},"abilities":{"str":16,"dex":13,"con":13,"int":7,"wis":11,"cha":8},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"4d10 + 4","skills":[{"name":"Perception","bonus":4}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Goblin","Worg"],"traits":[{"name":"Keen Hearing and Smell","text":"The worg has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"piercing","saveDc":13,"saveAbility":"str"}]}'),
    ('Wraith', '/icons/monsters/_mono/W.svg', 'medium', 'undead', '{"name":"Wraith","size":"medium","type":"undead","ac":13,"hp":67,"speed":{"walk":0,"fly":60,"hover":true},"abilities":{"str":6,"dex":16,"con":16,"int":12,"wis":14,"cha":15},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"9d8 + 27","damageResistances":["Acid","Cold","Fire","Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Necrotic","Poison"],"conditionImmunities":["Charmed","Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["The languages it knew in life"],"traits":[{"name":"Incorporeal Movement","text":"The wraith can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object."},{"name":"Sunlight Sensitivity","text":"While in sunlight, the wraith has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Life Drain","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 21 (4d8 + 3) necrotic damage. The target must succeed on a DC 14 Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","attackBonus":6,"reach":"5 ft","damage":"4d8+3","damageType":"necrotic","saveDc":14,"saveAbility":"con"},{"name":"Create Specter","text":"The wraith targets a humanoid within 10 feet of it that has been dead for no longer than 1 minute and died violently. The target''s spirit rises as a specter in the space of its corpse or in the nearest unoccupied space. The specter is under the wraith''s control. The wraith can have no more than seven specters under its control at one time."}]}'),
    ('Wyvern', '/icons/monsters/_mono/W.svg', 'large', 'dragon', '{"name":"Wyvern","size":"large","type":"dragon","ac":13,"hp":110,"speed":{"walk":20,"fly":80},"abilities":{"str":19,"dex":10,"con":16,"int":5,"wis":12,"cha":6},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"13d10 + 39","skills":[{"name":"Perception","bonus":4}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["--"],"actions":[{"name":"Multiattack","text":"The wyvern makes two attacks: one with its bite and one with its stinger. While flying, it can use its claws in place of one other attack."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one creature. Hit: 11 (2d6 + 4) piercing damage.","attackBonus":7,"reach":"10 ft","damage":"2d6+4","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"},{"name":"Stinger","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one creature. Hit: 11 (2d6 + 4) piercing damage. The target must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":7,"reach":"10 ft","damage":"2d6+4","damageType":"piercing","saveDc":15,"saveAbility":"con"}]}'),
    ('Xorn', '/icons/monsters/_mono/X.svg', 'medium', 'elemental', '{"name":"Xorn","size":"medium","type":"elemental","ac":19,"hp":73,"speed":{"walk":20,"burrow":20},"abilities":{"str":17,"dex":10,"con":22,"int":11,"wis":10,"cha":11},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"7d8 + 42","skills":[{"name":"Perception","bonus":6},{"name":"Stealth","bonus":3}],"damageResistances":["Piercing and Slashing from Nonmagical Attacks that aren''t Adamantine"],"senses":["Darkvision 60 ft.","Tremorsense 60 ft.","Passive Perception 16"],"languages":["Terran"],"traits":[{"name":"Earth Glide","text":"The xorn can burrow through nonmagical, unworked earth and stone. While doing so, the xorn doesn''t disturb the material it moves through."},{"name":"Stone Camouflage","text":"The xorn has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."},{"name":"Treasure Sense","text":"The xorn can pinpoint, by scent, the location of precious metals and stones, such as coins and gems, within 60 feet of it."}],"actions":[{"name":"Multiattack","text":"The xorn makes three claw attacks and one bite attack."},{"name":"Claw","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (3d6 + 3) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"3d6+3","damageType":"piercing"}]}'),
    ('Yeti', '/icons/monsters/_mono/Y.svg', 'large', 'monstrosity', '{"name":"Yeti","size":"large","type":"monstrosity","ac":12,"hp":51,"speed":{"walk":40,"climb":40},"abilities":{"str":18,"dex":13,"con":16,"int":8,"wis":12,"cha":7},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"6d10 + 18","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":3}],"damageImmunities":["Cold"],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["Yeti"],"traits":[{"name":"Fear of Fire","text":"If the yeti takes fire damage, it has disadvantage on attack rolls and ability checks until the end of its next turn."},{"name":"Keen Smell","text":"The yeti has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Snow Camouflage","text":"The yeti has advantage on Dexterity (Stealth) checks made to hide in snowy terrain."}],"actions":[{"name":"Multiattack","text":"The yeti can use its Chilling Gaze and makes two claw attacks."},{"name":"Claw","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) slashing damage plus 3 (1d6) cold damage.","attackBonus":6,"reach":"5 ft","damage":"1d6+4","damageType":"slashing"},{"name":"Chilling Gaze","text":"The yeti targets one creature it can see within 30 feet of it. If the target can see the yeti, the target must succeed on a DC 13 Constitution saving throw against this magic or take 10 (3d6) cold damage and then be paralyzed for 1 minute, unless it is immune to cold damage. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If the target''s saving throw is successful, or if the effect ends on it, the target is immune to the Chilling Gaze of all yetis (but not abominable yetis) for 1 hour.","saveDc":13,"saveAbility":"con"}]}'),
    ('Young Black Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Black Dragon","size":"large","type":"dragon","ac":18,"hp":127,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":19,"dex":14,"con":17,"int":12,"wis":11,"cha":15},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"15d10 + 45","saves":{"dex":5,"con":6,"wis":3,"cha":5},"skills":[{"name":"Perception","bonus":6},{"name":"Stealth","bonus":5}],"damageImmunities":["Acid"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 16"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) piercing damage plus 4 (1d8) acid damage.","attackBonus":7,"reach":"10 ft","damage":"2d10+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Acid Breath (Recharge 5–6)","text":"The dragon exhales acid in a 30­-foot line that is 5 feet wide. Each creature in that line must make a DC 14 Dexterity saving throw, taking 49 (11d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":14,"saveAbility":"dex"}]}'),
    ('Young Blue Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Blue Dragon","size":"large","type":"dragon","ac":18,"hp":152,"speed":{"walk":40,"burrow":20,"fly":80},"abilities":{"str":21,"dex":10,"con":19,"int":14,"wis":13,"cha":17},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"16d10 + 64","saves":{"dex":4,"con":8,"wis":5,"cha":7},"skills":[{"name":"Perception","bonus":9},{"name":"Stealth","bonus":4}],"damageImmunities":["Lightning"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 19"],"languages":["Common","Draconic"],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 16 (2d10 + 5) piercing damage plus 5 (1d10) lightning damage.","attackBonus":9,"reach":"10 ft","damage":"2d10+5","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage.","attackBonus":9,"reach":"5 ft","damage":"2d6+5","damageType":"slashing"},{"name":"Lightning Breath (Recharge 5–6)","text":"The dragon exhales lightning in an 60-foot line that is 5 feet wide. Each creature in that line must make a DC 16 Dexterity saving throw, taking 55 (10d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":16,"saveAbility":"dex"}]}'),
    ('Young Brass Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Brass Dragon","size":"large","type":"dragon","ac":17,"hp":110,"speed":{"walk":40,"burrow":20,"fly":80},"abilities":{"str":19,"dex":10,"con":17,"int":12,"wis":11,"cha":15},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"13d10 + 39","saves":{"dex":3,"con":6,"wis":3,"cha":5},"skills":[{"name":"Perception","bonus":6},{"name":"Persuasion","bonus":5},{"name":"Stealth","bonus":3}],"damageImmunities":["Fire"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 16"],"languages":["Common","Draconic"],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) piercing damage.","attackBonus":7,"reach":"10 ft","damage":"2d10+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Fire Breath","text":"The dragon exhales fire in a 40-foot line that is 5 feet wide. Each creature in that line must make a DC 14 Dexterity saving throw, taking 42 (12d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":14,"saveAbility":"dex"},{"name":"Sleep Breath","text":"The dragon exhales sleep gas in a 30-foot cone. Each creature in that area must succeed on a DC 14 Constitution saving throw or fall unconscious for 5 minutes. This effect ends for a creature if the creature takes damage or someone uses an action to wake it.","saveDc":14,"saveAbility":"con"}]}'),
    ('Young Bronze Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Bronze Dragon","size":"large","type":"dragon","ac":18,"hp":142,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":21,"dex":10,"con":19,"int":14,"wis":13,"cha":17},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"15d10 + 60","saves":{"dex":3,"con":7,"wis":4,"cha":6},"skills":[{"name":"Insight","bonus":4},{"name":"Perception","bonus":7},{"name":"Stealth","bonus":3}],"damageImmunities":["Lightning"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 17"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 16 (2d10 + 5) piercing damage.","attackBonus":8,"reach":"10 ft","damage":"2d10+5","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage.","attackBonus":8,"reach":"5 ft","damage":"2d6+5","damageType":"slashing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Lightning Breath","text":"The dragon exhales lightning in a 60- foot line that is 5 feet wide. Each creature in that line must make a DC 15 Dexterity saving throw, taking 55 (10d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":15,"saveAbility":"dex"},{"name":"Repulsion Breath","text":"The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a DC 15 Strength saving throw. On a failed save, the creature is pushed 40 feet away from the dragon.","saveDc":15,"saveAbility":"str"}]}'),
    ('Young Copper Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Copper Dragon","size":"large","type":"dragon","ac":17,"hp":119,"speed":{"walk":40,"climb":40,"fly":80},"abilities":{"str":19,"dex":12,"con":17,"int":16,"wis":13,"cha":15},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"14d10 + 42","saves":{"dex":4,"con":6,"wis":4,"cha":5},"skills":[{"name":"Deception","bonus":5},{"name":"Perception","bonus":7},{"name":"Stealth","bonus":4}],"damageImmunities":["Acid"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 17"],"languages":["Common","Draconic"],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) piercing damage.","attackBonus":7,"reach":"10 ft","damage":"2d10+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Acid Breath","text":"The dragon exhales acid in an 40-foot line that is 5 feet wide. Each creature in that line must make a DC 14 Dexterity saving throw, taking 40 (9d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":14,"saveAbility":"dex"},{"name":"Slowing Breath","text":"The dragon exhales gas in a 30-foot cone. Each creature in that area must succeed on a DC 14 Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save.","saveDc":14,"saveAbility":"con"}]}'),
    ('Young Gold Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Gold Dragon","size":"large","type":"dragon","ac":18,"hp":178,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":23,"dex":14,"con":21,"int":16,"wis":13,"cha":20},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"17d10 + 85","saves":{"dex":6,"con":9,"wis":5,"cha":9},"skills":[{"name":"Insight","bonus":5},{"name":"Perception","bonus":9},{"name":"Persuasion","bonus":9},{"name":"Stealth","bonus":6}],"damageImmunities":["Fire"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 19"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 17 (2d10 + 6) piercing damage.","attackBonus":10,"reach":"10 ft","damage":"2d10+6","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage.","attackBonus":10,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Fire Breath","text":"The dragon exhales fire in a 30-foot cone. Each creature in that area must make a DC 17 Dexterity saving throw, taking 55 (10d10) fire damage on a failed save, or half as much damage on a successful one.","saveDc":17,"saveAbility":"dex"},{"name":"Weakening Breath","text":"The dragon exhales gas in a 30-foot cone. Each creature in that area must succeed on a DC 17 Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":17,"saveAbility":"str"}]}'),
