    ('Young Red Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young Red Dragon","size":"large","type":"dragon","ac":18,"hp":178,"speed":{"walk":40,"climb":40,"fly":80},"abilities":{"str":23,"dex":10,"con":21,"int":14,"wis":11,"cha":19},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"17d10 + 85","saves":{"dex":4,"con":9,"wis":4,"cha":8},"skills":[{"name":"Perception","bonus":8},{"name":"Stealth","bonus":4}],"damageImmunities":["Fire"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 18"],"languages":["Common","Draconic"],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 17 (2d10 + 6) piercing damage plus 3 (1d6) fire damage.","attackBonus":10,"reach":"10 ft","damage":"2d10+6","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage.","attackBonus":10,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Fire Breath (Recharge 5–6)","text":"The dragon exhales fire in a 30-foot cone. Each creature in that area must make a DC 17 Dexterity saving throw, taking 56 (16d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":17,"saveAbility":"dex"}]}'),
