    ('Young White Dragon', '/icons/monsters/_mono/Y.svg', 'large', 'dragon', '{"name":"Young White Dragon","size":"large","type":"dragon","ac":17,"hp":133,"speed":{"walk":40,"burrow":20,"fly":80,"swim":40},"abilities":{"str":18,"dex":10,"con":18,"int":6,"wis":11,"cha":12},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"14d10 + 56","saves":{"dex":3,"con":7,"wis":3,"cha":4},"skills":[{"name":"Perception","bonus":6},{"name":"Stealth","bonus":3}],"damageImmunities":["Cold"],"senses":["Blindsight 30 ft.","Darkvision 120 ft.","Passive Perception 16"],"languages":["Common","Draconic"],"traits":[{"name":"Ice Walk","text":"The dragon can move across and climb icy surfaces without needing to make an ability check. Additionally, difficult terrain composed of ice or snow doesn''t cost it extra movement."}],"actions":[{"name":"Multiattack","text":"The dragon makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) piercing damage plus 4 (1d8) cold damage.","attackBonus":7,"reach":"10 ft","damage":"2d10+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Cold Breath (Recharge 5–6)","text":"The dragon exhales an icy blast in a 30-foot cone. Each creature in that area must make a DC 15 Constitution saving throw, taking 45 (10d8) cold damage on a failed save, or half as much damage on a successful one.","saveDc":15,"saveAbility":"con"}]}'),
    ('Zombie', '/icons/monsters/_mono/Z.svg', 'medium', 'undead', '{"name":"Zombie","size":"medium","type":"undead","ac":8,"hp":22,"speed":{"walk":20},"abilities":{"str":13,"dex":6,"con":16,"int":3,"wis":6,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"3d8 + 9","saves":{"wis":0},"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Undead Fortitude","text":"If damage reduces the zombie to 0 hit points, it must make a Constitution saving throw with a DC of 5 + the damage taken, unless the damage is radiant or from a critical hit. On a success, the zombie drops to 1 hit point instead."}],"actions":[{"name":"Slam","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"bludgeoning"}]}')
  ) as v(name, image_url, size, ctype, mb)
